/**
 * Parse a CommittedMetadata JSON into a SessionInfo object
 */
export function parseSessionMetadata(metadataText: string, promptText: string | null): SessionInfo | null {
  try {
    const parsed: CommittedMetadata = JSON.parse(metadataText);
    const tokenUsage = parsed.token_usage;
    const attribution = parsed.initial_attribution;

    return {
      prompt: promptText?.split("\n")[0] ?? null,
      agent: parsed.agent ?? "Claude Code",
      steps: parsed.checkpoints_count ?? 1,
      sessionId: parsed.session_id,
      createdAt: parsed.created_at,
      isTask: parsed.is_task,
      toolUseId: parsed.tool_use_id,
      transcriptIdentifierAtStart: parsed.transcript_identifier_at_start,
      checkpointTranscriptStart: parsed.checkpoint_transcript_start ?? parsed.transcript_lines_at_start,
      summary: parsed.summary,
      tokenUsage: tokenUsage ? {
        inputTokens: tokenUsage.input_tokens,
        cacheCreationTokens: tokenUsage.cache_creation_tokens,
        cacheReadTokens: tokenUsage.cache_read_tokens,
        outputTokens: tokenUsage.output_tokens,
        apiCallCount: tokenUsage.api_call_count,
      } : undefined,
      attribution: attribution ? {
        calculatedAt: attribution.calculated_at,
        agentLines: attribution.agent_lines,

  };
}

