  it("returns single agent when no sessions JSON", () => {
    const row = makeRow({ agent: "Cursor" })
    const info = mapCheckpointToInfo(row)

    expect(info.agents).toEqual(["Cursor"])
    expect(info.sessions).toHaveLength(1)
    expect(info.sessions[0].agent).toBe("Cursor")
  })

  it("returns multiple unique agents from sessions JSON", () => {
    const sessions = [
      { prompt: "p1", agent: "Claude Code", steps: 2 },
      { prompt: null, agent: "Mock Lifecycle Agent", steps: 1 },
    ]
    const row = makeRow({ sessions: JSON.stringify(sessions), session_count: 2 })
    const info = mapCheckpointToInfo(row)

    expect(info.agents).toEqual(["Claude Code", "Mock Lifecycle Agent"])
    expect(info.sessions).toHaveLength(2)
    expect(info.sessionCount).toBe(2)
  })

  it("deduplicates agents when multiple sessions use the same agent", () => {
    const sessions = [
      { prompt: "p1", agent: "Claude Code", steps: 2 },
      { prompt: "p2", agent: "Claude Code", steps: 3 },
    ]
    const row = makeRow({ sessions: JSON.stringify(sessions), session_count: 2 })
    const info = mapCheckpointToInfo(row)

    expect(info.agents).toEqual(["Claude Code"])
    expect(info.sessions).toHaveLength(2)
  })

  it("computes totalSteps from sessions", () => {
    const sessions = [
      { prompt: "p1", agent: "Claude Code", steps: 5 },
      { prompt: "p2", agent: "Cursor", steps: 3 },
    ]
    const row = makeRow({ sessions: JSON.stringify(sessions), session_count: 2 })
    const info = mapCheckpointToInfo(row)

    expect(info.totalSteps).toBe(8)
  })

  it("maps attribution when present", () => {
    const row = makeRow({
      attribution_calculated_at: "2026-03-10T14:00:00Z",
      attribution_agent_lines: 50,
      attribution_human_added: 10,
      attribution_human_modified: 5,
      attribution_human_removed: 2,
      attribution_total_committed: 67,
      attribution_agent_percentage: 75,
    })
    const info = mapCheckpointToInfo(row)

    expect(info.attribution).toEqual({
      calculatedAt: "2026-03-10T14:00:00Z",
      agentLines: 50,
      humanAdded: 10,
      humanModified: 5,
      humanRemoved: 2,
      totalCommitted: 67,
      agentPercentage: 75,
    })
  })

  it("returns null attribution when not calculated", () => {
    const row = makeRow({ attribution_calculated_at: null })
    const info = mapCheckpointToInfo(row)

    expect(info.attribution).toBeNull()
  })

  it("defaults checkpointRepoFullName to null when not provided", () => {
    const info = mapCheckpointToInfo(makeRow())

    expect(info.checkpointRepoFullName).toBeNull()
  })

  it("passes through checkpointRepoFullName when provided", () => {
    const info = mapCheckpointToInfo(makeRow(), "myorg/checkpoints-repo")

    expect(info.checkpointRepoFullName).toBe("myorg/checkpoints-repo")
  })
})

