describe("exchangeCodeForToken - retry logic", () => {
  const originalFetch = globalThis.fetch
  const originalSetTimeout = globalThis.setTimeout

  beforeEach(() => {
    vi.restoreAllMocks()
    // Mock setTimeout to execute immediately for faster tests
    vi.useFakeTimers()
  })

  afterEach(() => {
    globalThis.fetch = originalFetch
    vi.useRealTimers()
  })

  const createSuccessResponse = () => ({
    ok: true,
    json: async () => ({
      access_token: "gho_test_token_123",
      token_type: "bearer",
      scope: "repo,user",
    }),
  })

  const createErrorResponse = (status: number) => ({
    ok: false,
    status,
    body: { cancel: vi.fn() },
  })

  it("succeeds on first attempt without retry", async () => {
    const fetchMock = vi.fn().mockResolvedValue(createSuccessResponse())
    globalThis.fetch = fetchMock as typeof fetch

    const result = await exchangeCodeForToken(
      "test-code",
      "client-id",
      "client-secret",
      "http://localhost/callback",
    )

    expect(result.access_token).toBe("gho_test_token_123")
    expect(fetchMock).toHaveBeenCalledTimes(1)
  })

  it("retries once and succeeds after 503 error", async () => {
    const fetchMock = vi
      .fn()
      .mockResolvedValueOnce(createErrorResponse(503))
      .mockResolvedValueOnce(createSuccessResponse())

    globalThis.fetch = fetchMock as typeof fetch

    const promise = exchangeCodeForToken(
      "test-code",
      "client-id",
      "client-secret",
      "http://localhost/callback",
    )

    // Fast-forward through the retry delays
    await vi.runAllTimersAsync()
    const result = await promise

    expect(result.access_token).toBe("gho_test_token_123")
    expect(fetchMock).toHaveBeenCalledTimes(2)
  })

  it("retries multiple times before success (503, 503, success)", async () => {
    const fetchMock = vi
