describe("isValidGitHubOrgName", () => {
  describe("valid organization names", () => {
    it("accepts simple alphanumeric names", () => {
      expect(isValidGitHubOrgName("github")).toBe(true)
      expect(isValidGitHubOrgName("org123")).toBe(true)
      expect(isValidGitHubOrgName("123org")).toBe(true)
    })

    it("accepts names with hyphens in the middle", () => {
      expect(isValidGitHubOrgName("my-org")).toBe(true)
      expect(isValidGitHubOrgName("my-cool-org")).toBe(true)
      expect(isValidGitHubOrgName("a-b-c-d")).toBe(true)
    })

    it("accepts single character names", () => {
      expect(isValidGitHubOrgName("a")).toBe(true)
      expect(isValidGitHubOrgName("1")).toBe(true)
    })

    it("accepts two character names", () => {
      expect(isValidGitHubOrgName("ab")).toBe(true)
      expect(isValidGitHubOrgName("a1")).toBe(true)
    })

    it("accepts maximum length names (39 characters)", () => {
      expect(isValidGitHubOrgName("a".repeat(39))).toBe(true)
      expect(isValidGitHubOrgName("a" + "-".repeat(37) + "b")).toBe(true)
    })
  })

  describe("invalid organization names", () => {
    it("rejects empty string", () => {
      expect(isValidGitHubOrgName("")).toBe(false)
    })

    it("rejects names longer than 39 characters", () => {
      expect(isValidGitHubOrgName("a".repeat(40))).toBe(false)
      expect(isValidGitHubOrgName("a".repeat(100))).toBe(false)
    })

    it("rejects names starting with hyphen", () => {
      expect(isValidGitHubOrgName("-invalid")).toBe(false)
      expect(isValidGitHubOrgName("-")).toBe(false)
    })

    it("rejects names ending with hyphen", () => {
      expect(isValidGitHubOrgName("invalid-")).toBe(false)
    })
  })

  describe("security - SQL/LIKE injection patterns", () => {
    it("rejects wildcard characters", () => {
      expect(isValidGitHubOrgName("%")).toBe(false)
      expect(isValidGitHubOrgName("_")).toBe(false)
      expect(isValidGitHubOrgName("my%org")).toBe(false)
      expect(isValidGitHubOrgName("my_org")).toBe(false)
    })

    it("rejects SQL injection patterns", () => {
      expect(isValidGitHubOrgName("'; DROP TABLE repos; --")).toBe(false)
      expect(isValidGitHubOrgName("org' OR '1'='1")).toBe(false)
    })

    it("rejects path traversal patterns", () => {
      expect(isValidGitHubOrgName("../../../etc")).toBe(false)
      expect(isValidGitHubOrgName("org/repo")).toBe(false)
    })

    it("rejects unicode and special characters", () => {
      expect(isValidGitHubOrgName("org\u0000name")).toBe(false)
      expect(isValidGitHubOrgName("org name")).toBe(false)
      expect(isValidGitHubOrgName("org.name")).toBe(false)
    })
  })
})

