// Parse git trailers from a commit message
// Trailers are key-value pairs at the end of a commit message in the format "Key: Value"
// Returns arrays for each key to support multiple trailers with the same key (e.g., squashed commits)
export function parseTrailers(message: string): Record<string, string[]> {
  const trailers: Record<string, string[]> = {}
  const lines = message.split("\n")

  // Trailers are at the end of the message, after a blank line
  // Work backwards to find them
  let inTrailers = false
  for (let i = lines.length - 1; i >= 0; i--) {
    const line = lines[i].trim()

    // Empty line marks the boundary between body and trailers
    if (line === "") {
      if (inTrailers) break
      continue
    }

    // Check if line matches trailer format "Key: Value"
    const match = line.match(/^([A-Za-z0-9-]+):\s*(.+)$/)
    if (match) {
      inTrailers = true
      const key = match[1]
      if (!trailers[key]) {
        trailers[key] = []
      }
      // Use unshift to maintain original order (we're iterating backwards)
      trailers[key].unshift(match[2])
    } else if (inTrailers) {
      // Non-trailer line after we've seen trailers means we've gone too far
      break
    }
  }

  return trailers
}

// Extract all Entire-Checkpoint IDs from anywhere in a commit message
// This handles GitHub's squash-merge format where trailers are inline with each commit:
//   * commit message 1
//   Entire-Checkpoint: abc123
//   * commit message 2
//   Entire-Checkpoint: def456
export function extractCheckpointIds(message: string): string[] {
  const checkpointIds: string[] = []
  const regex = /^Entire-Checkpoint:\s*(\S+)/gm
  let match
  while ((match = regex.exec(message)) !== null) {
    checkpointIds.push(match[1])
  }
  return checkpointIds
}

// Parse GitHub squash commit format and return a map of checkpoint ID -> title
// GitHub squash format:
//   PR Title (#123)
//   * commit message 1
//   Entire-Checkpoint: abc123
//   * commit message 2
//   Entire-Checkpoint: def456
// Returns: { "abc123" => "PR Title (#123) * commit message 1", ... }
// Returns empty map if not in squash format (caller uses default behavior)
export function parseSquashCommitTitles(message: string): Map<string, string> {
  const result = new Map<string, string>()
  const lines = message.split("\n")

  // Check for PR title format: "Title (#123)"
  const prTitleMatch = lines[0]?.match(/^(.+\s+\(#\d+\))$/)
  if (!prTitleMatch) return result

  const prTitle = lines[0]
  let currentCommitMessage: string | null = null

  for (const line of lines.slice(1)) {
    const commitMatch = line.match(/^\*\s+(.+)$/)
    if (commitMatch) {
      currentCommitMessage = commitMatch[1]
      continue
    }

    const checkpointMatch = line.match(/^Entire-Checkpoint:\s*(\S+)/)
    if (checkpointMatch && currentCommitMessage) {
      result.set(checkpointMatch[1], `${prTitle} * ${currentCommitMessage}`)
      currentCommitMessage = null
    }
  }

  return result
}

// Fetch file content at a specific commit
export async function fetchFileAtCommit(
  repoFullName: string,
  path: string,
  sha: string,
  accessToken?: string,
): Promise<string | null> {
  const headers: Record<string, string> = {
    Accept: "application/vnd.github.raw+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
  }

  if (accessToken) {
    headers.Authorization = `Bearer ${accessToken}`
  }

  // Encode each path segment individually, not the whole path (/ must remain unencoded)
  const encodedPath = path.split("/").map(encodeURIComponent).join("/")
  const response = await fetch(
    `${GITHUB_API}/repos/${repoFullName}/contents/${encodedPath}?ref=${sha}`,
    { headers },
  )

  if (!response.ok) {
    // Cancel the response body to avoid stalled connections in Workers
    response.body?.cancel()
    // File might not exist in this commit
    if (response.status === 404) {
      return null
    }
    throw new Error(`Failed to fetch file: ${response.status}`)
  }

  // With Accept: application/vnd.github.raw+json, we get raw content directly
  return response.text()
}

// Result from discovering checkpoints on a working branch
export interface DiscoveredCheckpoint {
  checkpointId: string
  commit: CommitInfo
}

// Discover all checkpoints from a branch by scanning for Entire-Checkpoint trailers.
// Discovers ALL checkpoint IDs on the branch (no pre-known target set required).
// Supports `since` parameter for incremental sync (ISO 8601 date).
export async function discoverCheckpointsFromBranch(
  repoFullName: string,
  branch: string,
  token: string,
  since?: string,
  maxPages: number = 20,
): Promise<DiscoveredCheckpoint[]> {
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
    Authorization: `Bearer ${token}`,
  }

  const results: DiscoveredCheckpoint[] = []
  let page = 1
  const perPage = 100

  while (page <= maxPages) {
    let url = `${GITHUB_API}/repos/${repoFullName}/commits?sha=${encodeURIComponent(branch)}&per_page=${perPage}&page=${page}`
    if (since) {
      url += `&since=${encodeURIComponent(since)}`
    }

    const response = await fetch(url, { headers })

    // Check for rate limiting
    const rateLimitCheck = isRateLimited(response)
    if (rateLimitCheck.limited) {
      response.body?.cancel()
      throw new GitHubRateLimitError(
        "GitHub API rate limit exceeded",
        response.status,
        rateLimitCheck.resetAt,
      )
    }

    if (!response.ok) {
      response.body?.cancel()
      if (response.status === 404) {
        return []
      }
      throw new Error(`Failed to fetch branch commits: ${response.status}`)
    }

    const commits = await response.json<
      Array<{
        sha: string
        commit: {
          message: string
          author: {
            name: string
            date: string
          }
        }
        author: {
          login: string
          id: number
        } | null
        html_url: string
      }>
    >()

    for (const commit of commits) {
      // Extract all checkpoint IDs from anywhere in the message
      // This handles both standard trailers and GitHub's squash-merge format
      const checkpointIds = extractCheckpointIds(commit.commit.message)

      for (const checkpointId of checkpointIds) {
        results.push({
          checkpointId,
          commit: {
            sha: commit.sha,
            message: commit.commit.message,
            author: commit.commit.author.name,
            authorUsername: commit.author?.login ?? null,
            authorId: commit.author?.id ?? null,
            date: commit.commit.author.date,
            url: commit.html_url,
          },
        })
      }
    }

    if (commits.length < perPage) {
      break
    }
    page++
  }

  return results
}

// ============================================================================
// Trail functions
// ============================================================================

// Validation for trail IDs (same format as checkpoint IDs)
const TRAIL_ID_PATTERN = /^[a-f0-9]+$/i

export function isValidTrailId(trailId: string): boolean {
  return TRAIL_ID_PATTERN.test(trailId) && trailId.length >= 4 && trailId.length <= 64
}

/**
 * Generate a unique trail ID (12 hex characters)
 */
export function generateTrailId(): string {
  const array = new Uint8Array(6)
  crypto.getRandomValues(array)
  return Array.from(array, (b) => b.toString(16).padStart(2, "0")).join("")
}

/**
 * Discover all trail IDs from the entire/trails/v1 branch by listing directory structure
 */
export async function discoverTrailsFromBranch(
  repoFullName: string,
  token: string,
): Promise<string[]> {
  const [owner, repo] = repoFullName.split("/")

  // Query to list top-level directories in the trails branch
  const query = `
    query ListTrails($owner: String!, $repo: String!, $expression: String!) {
      repository(owner: $owner, name: $repo) {
        object(expression: $expression) {
          ... on Tree {
            entries {
              name
              type
              object {
                ... on Tree {
                  entries {
                    name
                    type
                  }
                }
              }
            }
          }
        }
      }
    }
  `

  try {
    const result = await githubGraphQL<{
      repository: {
        object: {
          entries: Array<{
            name: string
            type: string
            object?: {
              entries: Array<{
                name: string
                type: string
              }>
            }
          }>
        } | null
      }
    }>(token, query, { owner, repo, expression: `${TRAILS_BRANCH}:` })

    if (!result.repository?.object?.entries) {
      return []
    }

    const trailIds: string[] = []

    // Each top-level entry is a 2-char prefix directory
    for (const prefixDir of result.repository.object.entries) {
      if (prefixDir.type !== "tree" || prefixDir.name.length !== 2) continue

      // Each subdirectory is the rest of the trail ID
      if (prefixDir.object?.entries) {
        for (const trailDir of prefixDir.object.entries) {
          if (trailDir.type !== "tree") continue
          const trailId = prefixDir.name + trailDir.name
          if (isValidTrailId(trailId)) {
            trailIds.push(trailId)
          }
        }
      }
    }

    return trailIds
  } catch (error) {
    // Branch might not exist
    console.error(`[discoverTrailsFromBranch] Error: ${error}`)
    return []
  }
}

/**
 * Fetch trail data (metadata + discussion) for multiple trails in a batch
 */
export async function fetchTrailDataBatch(
  repoFullName: string,
  trailIds: string[],
  token: string,
): Promise<Map<string, Trail>> {
  const results = new Map<string, Trail>()

  if (trailIds.length === 0) return results

  // Filter to valid trail IDs
  const validTrailIds = trailIds.filter((id) => isValidTrailId(id))
  if (validTrailIds.length === 0) return results

  const [owner, repo] = repoFullName.split("/")

  // Batch trails to avoid GraphQL query size limits, fetch batches concurrently
  const TRAILS_PER_BATCH = 20
  const batches: string[][] = []
  for (let i = 0; i < validTrailIds.length; i += TRAILS_PER_BATCH) {
    batches.push(validTrailIds.slice(i, i + TRAILS_PER_BATCH))
  }

  await mapWithConcurrency(batches, async (batch: string[]) => {
    const fileQueries = batch
      .map((trailId: string, idx: number) => {
        const folderPath = `${trailId.slice(0, 2)}/${trailId.slice(2)}`
        return `
          t${idx}_meta: object(expression: "${TRAILS_BRANCH}:${folderPath}/metadata.json") { ... on Blob { text } }
          t${idx}_disc: object(expression: "${TRAILS_BRANCH}:${folderPath}/discussion.json") { ... on Blob { text } }
          t${idx}_ckpt: object(expression: "${TRAILS_BRANCH}:${folderPath}/checkpoints.json") { ... on Blob { text } }
          t${idx}_revw: object(expression: "${TRAILS_BRANCH}:${folderPath}/reviews.json") { ... on Blob { text } }
        `
      })
      .join("\n")

    const query = `
      query TrailData($owner: String!, $repo: String!) {
        repository(owner: $owner, name: $repo) {
          ${fileQueries}
        }
      }
    `

    try {
      const result = await githubGraphQLPartial<{
        repository: Record<string, { text: string } | null>
      }>(token, query, { owner, repo })

      if (result.data?.repository) {
        for (let idx = 0; idx < batch.length; idx++) {
          const trailId = batch[idx]
          const repoData = result.data.repository

          const metaBlob = repoData[`t${idx}_meta`]
          const discBlob = repoData[`t${idx}_disc`]
          const ckptBlob = repoData[`t${idx}_ckpt`]
          const revwBlob = repoData[`t${idx}_revw`]

          if (metaBlob?.text) {
            try {
              const metadata = JSON.parse(metaBlob.text) as TrailMetadata

              let discussion: TrailDiscussion = { comments: [] }
              if (discBlob?.text) {
                try {
                  discussion = JSON.parse(discBlob.text)
                } catch {
                  console.warn(`[fetchTrailDataBatch] Invalid discussion JSON for trail ${trailId}`)
                }
              }

              let checkpoints: TrailCheckpoints = { checkpoints: [] }
              if (ckptBlob?.text) {
                try {
                  checkpoints = JSON.parse(ckptBlob.text)
                } catch {
                  console.warn(
                    `[fetchTrailDataBatch] Invalid checkpoints JSON for trail ${trailId}`,
                  )
                }
              }

              let reviews: TrailReviews = { reviews: [] }
              if (revwBlob?.text) {
                try {
                  reviews = JSON.parse(revwBlob.text)
                } catch {
                  console.warn(`[fetchTrailDataBatch] Invalid reviews JSON for trail ${trailId}`)
                }
              }

              results.set(trailId, { metadata, discussion, checkpoints, reviews })
            } catch {
              console.warn(`[fetchTrailDataBatch] Invalid metadata JSON for trail ${trailId}`)
            }
          }
        }
      }
    } catch (error) {
      console.error(`[fetchTrailDataBatch] Error fetching batch: ${error}`)
    }
  })

  return results
}

/**
 * Lightweight variant of fetchTrailDataBatch that only fetches metadata + checkpoints
 * (skips discussion.json). Used by webhook trail linkage to reduce latency.
 */
export async function fetchTrailMetadataAndCheckpointsBatch(
  repoFullName: string,
  trailIds: string[],
  token: string,
): Promise<Map<string, { metadata: TrailMetadata; checkpoints: TrailCheckpoints }>> {
  const results = new Map<string, { metadata: TrailMetadata; checkpoints: TrailCheckpoints }>()

  if (trailIds.length === 0) return results

  const validTrailIds = trailIds.filter((id) => isValidTrailId(id))
  if (validTrailIds.length === 0) return results

  const [owner, repo] = repoFullName.split("/")

  const TRAILS_PER_BATCH = 20
  const batches: string[][] = []
  for (let i = 0; i < validTrailIds.length; i += TRAILS_PER_BATCH) {
    batches.push(validTrailIds.slice(i, i + TRAILS_PER_BATCH))
  }

  await mapWithConcurrency(batches, async (batch: string[]) => {
    const fileQueries = batch
      .map((trailId: string, idx: number) => {
        const folderPath = `${trailId.slice(0, 2)}/${trailId.slice(2)}`
        return `
          t${idx}_meta: object(expression: "${TRAILS_BRANCH}:${folderPath}/metadata.json") { ... on Blob { text } }
          t${idx}_ckpt: object(expression: "${TRAILS_BRANCH}:${folderPath}/checkpoints.json") { ... on Blob { text } }
        `
      })
      .join("\n")

    const query = `
      query TrailMetaCheckpoints($owner: String!, $repo: String!) {
        repository(owner: $owner, name: $repo) {
          ${fileQueries}
        }
      }
    `

    try {
      const result = await githubGraphQLPartial<{
        repository: Record<string, { text: string } | null>
      }>(token, query, { owner, repo })

      if (result.data?.repository) {
        for (let idx = 0; idx < batch.length; idx++) {
          const trailId = batch[idx]
          const repoData = result.data.repository

          const metaBlob = repoData[`t${idx}_meta`]
          const ckptBlob = repoData[`t${idx}_ckpt`]

          if (metaBlob?.text) {
            try {
              const metadata = JSON.parse(metaBlob.text) as TrailMetadata

              let checkpoints: TrailCheckpoints = { checkpoints: [] }
              if (ckptBlob?.text) {
                try {
                  checkpoints = JSON.parse(ckptBlob.text)
                } catch {
                  console.warn(
                    `[fetchTrailMetadataAndCheckpointsBatch] Invalid checkpoints JSON for trail ${trailId}`,
                  )
                }
              }

              results.set(trailId, { metadata, checkpoints })
            } catch {
              console.warn(
                `[fetchTrailMetadataAndCheckpointsBatch] Invalid metadata JSON for trail ${trailId}`,
              )
            }
          }
        }
      }
    } catch (error) {
      console.error(`[fetchTrailMetadataAndCheckpointsBatch] Error fetching batch: ${error}`)
    }
  })

  return results
}

/**
 * Ensure the entire/trails/v1 branch exists, creating it as an orphan branch if needed
 */
export async function ensureTrailsBranchExists(
  repoFullName: string,
  accessToken: string,
): Promise<void> {
  const exists = await checkBranchExists(repoFullName, TRAILS_BRANCH, accessToken)
  if (exists) return

  const [owner, repo] = repoFullName.split("/")
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
    Authorization: `Bearer ${accessToken}`,
  }

  // Create an orphan branch with a .gitkeep file
  // Step 1: Create blob for .gitkeep
  const blobResponse = await fetch(`${GITHUB_API}/repos/${owner}/${repo}/git/blobs`, {
    method: "POST",
    headers: { ...headers, "Content-Type": "application/json" },
    body: JSON.stringify({
      content: "",
      encoding: "utf-8",
    }),
  })

  if (!blobResponse.ok) {
    throw new Error(`Failed to create blob: ${blobResponse.status}`)
  }
  const blobData = await blobResponse.json<{ sha: string }>()

  // Step 2: Create tree with .gitkeep
  const treeResponse = await fetch(`${GITHUB_API}/repos/${owner}/${repo}/git/trees`, {
    method: "POST",
    headers: { ...headers, "Content-Type": "application/json" },
    body: JSON.stringify({
      tree: [
        {
          path: ".gitkeep",
          mode: "100644",
          type: "blob",
          sha: blobData.sha,
        },
      ],
    }),
  })

  if (!treeResponse.ok) {
    throw new Error(`Failed to create tree: ${treeResponse.status}`)
  }
  const treeData = await treeResponse.json<{ sha: string }>()

  // Step 3: Create commit with no parents (orphan)
  const commitResponse = await fetch(`${GITHUB_API}/repos/${owner}/${repo}/git/commits`, {
    method: "POST",
    headers: { ...headers, "Content-Type": "application/json" },
    body: JSON.stringify({
      message: "Initialize trails branch",
      tree: treeData.sha,
      parents: [],
    }),
  })

  if (!commitResponse.ok) {
    throw new Error(`Failed to create commit: ${commitResponse.status}`)
  }
  const commitData = await commitResponse.json<{ sha: string }>()

  // Step 4: Create branch ref
  const refResponse = await fetch(`${GITHUB_API}/repos/${owner}/${repo}/git/refs`, {
    method: "POST",
    headers: { ...headers, "Content-Type": "application/json" },
    body: JSON.stringify({
      ref: `refs/heads/${TRAILS_BRANCH}`,
      sha: commitData.sha,
    }),
  })

  if (!refResponse.ok) {
    // 422 means the branch was created by a concurrent request, which is fine
    if (refResponse.status === 422) {
      return
    }
    throw new Error(`Failed to create ref: ${refResponse.status}`)
  }
}

/**
 * Check if a head branch has been fully merged into a base branch.
 * Uses GitHub's compare API: ahead_by === 0 means all head commits are in base.
 */
export async function isBranchMergedInto(
  repoFullName: string,
  base: string,
  head: string,
  accessToken: string,
): Promise<boolean | null> {
  const headers = {
    Accept: "application/vnd.github+json",
    Authorization: `Bearer ${accessToken}`,
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
  }

  const response = await fetch(
    `${GITHUB_API}/repos/${repoFullName}/compare/${encodeURIComponent(base)}...${encodeURIComponent(head)}`,
    { headers },
  )

  if (!response.ok) {
    const body = await response.text()
    // 404 = branch deleted or ref doesn't exist
    if (response.status === 404) {
      return null
    }
    throw new Error(`GitHub compare API failed for ${base}...${head}: ${response.status} ${body}`)
  }

  const data = await response.json<{ ahead_by: number }>()
  return data.ahead_by === 0
}

/**
 * Resolve a branch name to its HEAD commit SHA.
 * Returns null if the branch does not exist (404).
 */
export async function resolveBranchSha(
  repoFullName: string,
  branch: string,
  accessToken: string,
): Promise<string | null> {
  const headers = {
    Accept: "application/vnd.github+json",
    Authorization: `Bearer ${accessToken}`,
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
  }

  const response = await fetch(
    `${GITHUB_API}/repos/${repoFullName}/git/ref/heads/${encodeURIComponent(branch)}`,
    { headers },
  )

  if (!response.ok) {
    response.body?.cancel()
    if (response.status === 404) return null
    throw new Error(`Failed to resolve branch ${branch}: ${response.status}`)
  }

  const data = await response.json<{ object: { sha: string } }>()
  return data.object.sha
}

/**
 * Get the merge-base commit SHA between two refs using the compare API.
 * Returns null if either ref doesn't exist (404).
 */
export async function getMergeBaseSha(
  repoFullName: string,
  base: string,
  head: string,
  accessToken: string,
): Promise<string | null> {
  const headers = {
    Accept: "application/vnd.github+json",
    Authorization: `Bearer ${accessToken}`,
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
  }

  const response = await fetch(
    `${GITHUB_API}/repos/${repoFullName}/compare/${encodeURIComponent(base)}...${encodeURIComponent(head)}`,
    { headers },
  )

  if (!response.ok) {
    response.body?.cancel()
    if (response.status === 404) return null
    const body = await response.text()
    throw new Error(`GitHub compare API failed for ${base}...${head}: ${response.status} ${body}`)
  }

  const data = await response.json<{ merge_base_commit: { sha: string } }>()
  return data.merge_base_commit.sha
}

/**
 * Compare two branches and return file-level diffs.
 * Uses GitHub's compare API to get the full diff between base and head.
 */
export async function compareBranches(
  repoFullName: string,
  base: string,
  head: string,
  accessToken: string,
): Promise<{ files: FileStats[]; additions: number; deletions: number }> {
  const headers = {
    Accept: "application/vnd.github+json",
    Authorization: `Bearer ${accessToken}`,
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
  }

  const response = await fetch(
    `${GITHUB_API}/repos/${repoFullName}/compare/${encodeURIComponent(base)}...${encodeURIComponent(head)}`,
    { headers },
  )

  const rateLimitCheck = isRateLimited(response)
  if (rateLimitCheck.limited) {
    response.body?.cancel()
    throw new GitHubRateLimitError(
      "GitHub API rate limit exceeded",
      response.status,
      rateLimitCheck.resetAt,
    )
  }

  if (!response.ok) {
    if (response.status === 404) {
      response.body?.cancel()
      return { files: [], additions: 0, deletions: 0 }
    }
    const body = await response.text()
    throw new Error(`GitHub compare API failed for ${base}...${head}: ${response.status} ${body}`)
  }

  const data = await response.json<{
    files?: Array<{
      filename: string
      status: string
      additions: number
      deletions: number
      patch?: string
    }>
    total_commits: number
  }>()

  const rawFiles = data.files ?? []
  const files = applyPatchLimits(rawFiles)
  const totalAdditions = rawFiles.reduce((sum, f) => sum + f.additions, 0)
  const totalDeletions = rawFiles.reduce((sum, f) => sum + f.deletions, 0)

  return { files, additions: totalAdditions, deletions: totalDeletions }
}

/**
 * Find a closed/merged PR by head and base branch, then return its files.
 * Used as fallback when the feature branch has been deleted after merge.
 */
export async function fetchPullRequestFiles(
  repoFullName: string,
  base: string,
  head: string,
  accessToken: string,
): Promise<{ files: FileStats[]; additions: number; deletions: number }> {
  const headers = {
    Accept: "application/vnd.github+json",
    Authorization: `Bearer ${accessToken}`,
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
  }

  const [owner] = repoFullName.split("/")

  // Find a merged PR by head branch and base branch
  // Fetch a few results in case the most recent closed PR was closed without merging
  const searchUrl = `${GITHUB_API}/repos/${repoFullName}/pulls?state=closed&head=${encodeURIComponent(`${owner}:${head}`)}&base=${encodeURIComponent(base)}&sort=updated&direction=desc&per_page=5`
  const searchRes = await fetch(searchUrl, { headers })

  const rateLimitCheck = isRateLimited(searchRes)
  if (rateLimitCheck.limited) {
    searchRes.body?.cancel()
    throw new GitHubRateLimitError(
      "GitHub API rate limit exceeded",
      searchRes.status,
      rateLimitCheck.resetAt,
    )
  }

  if (!searchRes.ok) {
    await searchRes.text() // consume body
    return { files: [], additions: 0, deletions: 0 }
  }

  const prs = await searchRes.json<Array<{ number: number; merged_at: string | null }>>()
  const mergedPr = prs.find((pr) => pr.merged_at !== null)
  if (!mergedPr) {
    return { files: [], additions: 0, deletions: 0 }
  }

  // Fetch PR files (paginated, up to 300 files)
  const allFiles: Array<{
    filename: string
    status: string
    additions: number
    deletions: number
    patch?: string
  }> = []
  let page = 1
  while (page <= 3) {
    const filesRes = await fetch(
      `${GITHUB_API}/repos/${repoFullName}/pulls/${mergedPr.number}/files?per_page=100&page=${page}`,
      { headers },
    )
    const paginationRateLimit = isRateLimited(filesRes)
    if (paginationRateLimit.limited) {
      filesRes.body?.cancel()
      throw new GitHubRateLimitError(
        "GitHub API rate limit exceeded",
        filesRes.status,
        paginationRateLimit.resetAt,
      )
    }
    if (!filesRes.ok) {
      filesRes.body?.cancel()
      break
    }
    const batch = await filesRes.json<
      Array<{
        filename: string
        status: string
        additions: number
        deletions: number
        patch?: string
      }>
    >()
    if (batch.length === 0) break
    allFiles.push(...batch)
    if (batch.length < 100) break
    page++
  }

  const files = applyPatchLimits(allFiles)
  const totalAdditions = allFiles.reduce((sum, f) => sum + f.additions, 0)
  const totalDeletions = allFiles.reduce((sum, f) => sum + f.deletions, 0)

  return { files, additions: totalAdditions, deletions: totalDeletions }
}

/**
 * Create a GitHub pull request. If one already exists for the same head/base, return its number.
 */
export async function createPullRequest(
  repoFullName: string,
  head: string,
  base: string,
  title: string,
  body: string,
  accessToken: string,
  options?: { prBody?: string },
): Promise<number> {
  const prBody = options?.prBody ?? body
  const [owner, repo] = repoFullName.split("/")
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
    Authorization: `Bearer ${accessToken}`,
    "Content-Type": "application/json",
  }

  // Check for an existing closed PR for this head/base and reopen it
  const closedListResponse = await fetchWithRetry(
    `${GITHUB_API}/repos/${owner}/${repo}/pulls?head=${encodeURIComponent(`${owner}:${head}`)}&base=${encodeURIComponent(base)}&state=closed`,
    { headers },
  )
  if (closedListResponse.ok) {
    const closedPrs =
      await closedListResponse.json<{ number: number; merged_at: string | null }[]>()
    // Only reopen PRs that were closed without merging
    const unmergedPr = closedPrs.find((pr) => pr.merged_at === null)
    if (unmergedPr) {
      const reopenResponse = await fetchWithRetry(
        `${GITHUB_API}/repos/${owner}/${repo}/pulls/${unmergedPr.number}`,
        {
          method: "PATCH",
          headers,
          body: JSON.stringify({ state: "open", title, body: prBody }),
        },
      )
      if (reopenResponse.ok) {
        return unmergedPr.number
      }
      // If reopen fails (e.g. branch deleted), fall through to create a new one
    }
  }

  const response = await fetchWithRetry(`${GITHUB_API}/repos/${owner}/${repo}/pulls`, {
    method: "POST",
    headers,
    body: JSON.stringify({ title, head, base, body: prBody }),
  })

  if (response.ok) {
    const data = await response.json<{ number: number }>()
    return data.number
  }

  // If an open PR already exists for this head/base, return it
  if (response.status === 422) {
    const errorText = await response.text()
    if (errorText.includes("A pull request already exists")) {
      const listResponse = await fetchWithRetry(
        `${GITHUB_API}/repos/${owner}/${repo}/pulls?head=${encodeURIComponent(`${owner}:${head}`)}&base=${encodeURIComponent(base)}&state=open`,
        { headers },
      )
      if (listResponse.ok) {
        const prs = await listResponse.json<{ number: number }[]>()
        if (prs.length > 0) {
          return prs[0].number
        }
      }
    }
    throw new Error(`Failed to create pull request: 422 - ${errorText}`)
  }

  throw new Error(`Failed to create pull request: ${response.status}`)
}

/**
 * Create a new branch from a base branch if it doesn't already exist
 * Returns true if created, false if already existed
 */
export async function createBranchIfNotExists(
  repoFullName: string,
  branchName: string,
  baseBranch: string,
  accessToken: string,
): Promise<boolean> {
  const exists = await checkBranchExists(repoFullName, branchName, accessToken)
  if (exists) return false

  const [owner, repo] = repoFullName.split("/")
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
    Authorization: `Bearer ${accessToken}`,
  }

  // Get base branch SHA
  const baseResponse = await fetch(
    `${GITHUB_API}/repos/${owner}/${repo}/branches/${encodeURIComponent(baseBranch)}`,
    { headers },
  )

  if (!baseResponse.ok) {
    throw new Error(`Base branch '${baseBranch}' not found: ${baseResponse.status}`)
  }
  const baseData = await baseResponse.json<{ commit: { sha: string } }>()

  // Create branch ref
  const refResponse = await fetch(`${GITHUB_API}/repos/${owner}/${repo}/git/refs`, {
    method: "POST",
    headers: { ...headers, "Content-Type": "application/json" },
    body: JSON.stringify({
      ref: `refs/heads/${branchName}`,
      sha: baseData.commit.sha,
    }),
  })

  if (!refResponse.ok) {
    const error = await refResponse.text()
    // 422 with "Reference already exists" means a concurrent request created it, which is fine
    if (refResponse.status === 422 && error.includes("Reference already exists")) {
      return false
    }
    throw new Error(`Failed to create branch: ${refResponse.status} - ${error}`)
  }

  return true
}

/**
 * Commit trail metadata, discussion, checkpoints, and reviews files to the entire/trails/v1 branch
 *
 * Trail structure in entire/trails/v1 branch:
 *   {id[0:2]}/{id[2:]}/
 *     ├── metadata.json     - Trail metadata (title, status, assignees, etc.)
 *     ├── discussion.json   - Comments and threads
 *     ├── checkpoints.json  - References to checkpoints on this trail
 *     └── reviews.json      - Native review events
 */
export async function commitTrailFiles(
  repoFullName: string,
  trailId: string,
  metadata: TrailMetadata,
  discussion: TrailDiscussion,
  checkpoints: TrailCheckpoints,
  accessToken: string,
  commitMessage: string,
): Promise<void> {
  const [owner, repo] = repoFullName.split("/")
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
    Authorization: `Bearer ${accessToken}`,
  }

  // Ensure trails branch exists
  await ensureTrailsBranchExists(repoFullName, accessToken)

  const prefix = `${trailId.slice(0, 2)}/${trailId.slice(2)}`

  // Get current ref SHA
  const refResponse = await fetch(
    `${GITHUB_API}/repos/${owner}/${repo}/git/refs/heads/${TRAILS_BRANCH}`,
    { headers },
  )

  if (!refResponse.ok) {
    throw new Error(`Failed to get ref: ${refResponse.status}`)
  }
  const refData = await refResponse.json<{ object: { sha: string } }>()
  const baseCommitSha = refData.object.sha

  // Get base tree
  const commitResponse = await fetch(
    `${GITHUB_API}/repos/${owner}/${repo}/git/commits/${baseCommitSha}`,
    { headers },
  )
  if (!commitResponse.ok) {
    throw new Error(`Failed to get commit: ${commitResponse.status}`)
  }
  const commitData = await commitResponse.json<{ tree: { sha: string } }>()
  const baseTreeSha = commitData.tree.sha

  // Create blobs for metadata.json, discussion.json, and checkpoints.json
  const metadataBlob = await fetch(`${GITHUB_API}/repos/${owner}/${repo}/git/blobs`, {
    method: "POST",
    headers: { ...headers, "Content-Type": "application/json" },
    body: JSON.stringify({
      content: JSON.stringify(metadata, null, 2),
      encoding: "utf-8",
    }),
  })
  if (!metadataBlob.ok) {
    throw new Error(`Failed to create metadata blob: ${metadataBlob.status}`)
  }
  const metadataBlobData = await metadataBlob.json<{ sha: string }>()

  const discussionBlob = await fetch(`${GITHUB_API}/repos/${owner}/${repo}/git/blobs`, {
    method: "POST",
    headers: { ...headers, "Content-Type": "application/json" },
    body: JSON.stringify({
      content: JSON.stringify(discussion, null, 2),
      encoding: "utf-8",
    }),
  })
  if (!discussionBlob.ok) {
    throw new Error(`Failed to create discussion blob: ${discussionBlob.status}`)
  }
  const discussionBlobData = await discussionBlob.json<{ sha: string }>()

  const checkpointsBlob = await fetch(`${GITHUB_API}/repos/${owner}/${repo}/git/blobs`, {
    method: "POST",
    headers: { ...headers, "Content-Type": "application/json" },
    body: JSON.stringify({
      content: JSON.stringify(checkpoints, null, 2),
      encoding: "utf-8",
    }),
  })
  if (!checkpointsBlob.ok) {
    throw new Error(`Failed to create checkpoints blob: ${checkpointsBlob.status}`)
  }
  const checkpointsBlobData = await checkpointsBlob.json<{ sha: string }>()

  const reviewsBlob = await fetch(`${GITHUB_API}/repos/${owner}/${repo}/git/blobs`, {
    method: "POST",
    headers: { ...headers, "Content-Type": "application/json" },
    body: JSON.stringify({
      content: JSON.stringify({ reviews: [] }, null, 2),
      encoding: "utf-8",
    }),
  })
  if (!reviewsBlob.ok) {
    throw new Error(`Failed to create reviews blob: ${reviewsBlob.status}`)
  }
  const reviewsBlobData = await reviewsBlob.json<{ sha: string }>()

  // Create tree with new files
  const treeResponse = await fetch(`${GITHUB_API}/repos/${owner}/${repo}/git/trees`, {
    method: "POST",
    headers: { ...headers, "Content-Type": "application/json" },
    body: JSON.stringify({
      base_tree: baseTreeSha,
      tree: [
        {
          path: `${prefix}/metadata.json`,
          mode: "100644",
          type: "blob",
          sha: metadataBlobData.sha,
        },
        {
          path: `${prefix}/discussion.json`,
          mode: "100644",
          type: "blob",
          sha: discussionBlobData.sha,
        },
        {
          path: `${prefix}/checkpoints.json`,
          mode: "100644",
          type: "blob",
          sha: checkpointsBlobData.sha,
        },
        {
          path: `${prefix}/reviews.json`,
          mode: "100644",
          type: "blob",
          sha: reviewsBlobData.sha,
        },
      ],
    }),
  })
  if (!treeResponse.ok) {
    throw new Error(`Failed to create tree: ${treeResponse.status}`)
  }
  const treeData = await treeResponse.json<{ sha: string }>()

  // Create commit
  const newCommitResponse = await fetch(`${GITHUB_API}/repos/${owner}/${repo}/git/commits`, {
    method: "POST",
    headers: { ...headers, "Content-Type": "application/json" },
    body: JSON.stringify({
      message: commitMessage,
      tree: treeData.sha,
      parents: [baseCommitSha],
    }),
  })
  if (!newCommitResponse.ok) {
    throw new Error(`Failed to create commit: ${newCommitResponse.status}`)
  }
  const newCommitData = await newCommitResponse.json<{ sha: string }>()

  // Update ref
  const updateRefResponse = await fetch(
    `${GITHUB_API}/repos/${owner}/${repo}/git/refs/heads/${TRAILS_BRANCH}`,
    {
      method: "PATCH",
      headers: { ...headers, "Content-Type": "application/json" },
      body: JSON.stringify({ sha: newCommitData.sha }),
    },
  )
  if (!updateRefResponse.ok) {
    throw new Error(`Failed to update ref: ${updateRefResponse.status}`)
  }
}

/**
 * Generate a random comment ID (8 hex characters)
 */
export function generateCommentId(): string {
  const array = new Uint8Array(4)
  crypto.getRandomValues(array)
  return Array.from(array, (b) => b.toString(16).padStart(2, "0")).join("")
}

/**
 * Update just the discussion.json file for a trail
 */
/**
 * Generic helper to update a single JSON file in a trail folder on the trails branch.
 * Handles the 5-step GitHub Git API flow: get ref → get commit → create blob → create tree → create commit → update ref.
 */
async function updateTrailFile(
  repoFullName: string,
  trailId: string,
  fileName: string,
  content: unknown,
  accessToken: string,
  commitMessage: string,
): Promise<void> {
  const [owner, repo] = repoFullName.split("/")
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
    Authorization: `Bearer ${accessToken}`,
  }

  const prefix = `${trailId.slice(0, 2)}/${trailId.slice(2)}`

  // Get current ref SHA
  const refResponse = await fetch(
    `${GITHUB_API}/repos/${owner}/${repo}/git/refs/heads/${TRAILS_BRANCH}`,
    { headers },
  )
  if (!refResponse.ok) {
    throw new Error(`Failed to get ref: ${refResponse.status}`)
  }
  const refData = await refResponse.json<{ object: { sha: string } }>()
  const baseCommitSha = refData.object.sha

  // Get base tree
  const commitResponse = await fetch(
    `${GITHUB_API}/repos/${owner}/${repo}/git/commits/${baseCommitSha}`,
    { headers },
  )
  if (!commitResponse.ok) {
    throw new Error(`Failed to get commit: ${commitResponse.status}`)
  }
  const commitData = await commitResponse.json<{ tree: { sha: string } }>()
  const baseTreeSha = commitData.tree.sha

  // Create blob
  const blobResponse = await fetch(`${GITHUB_API}/repos/${owner}/${repo}/git/blobs`, {
    method: "POST",
    headers: { ...headers, "Content-Type": "application/json" },
    body: JSON.stringify({
      content: JSON.stringify(content, null, 2),
      encoding: "utf-8",
    }),
  })
  if (!blobResponse.ok) {
    throw new Error(`Failed to create blob for ${fileName}: ${blobResponse.status}`)
  }
  const blobData = await blobResponse.json<{ sha: string }>()

  // Create tree
  const treeResponse = await fetch(`${GITHUB_API}/repos/${owner}/${repo}/git/trees`, {
    method: "POST",
    headers: { ...headers, "Content-Type": "application/json" },
    body: JSON.stringify({
      base_tree: baseTreeSha,
      tree: [
        {
          path: `${prefix}/${fileName}`,
          mode: "100644",
          type: "blob",
          sha: blobData.sha,
        },
      ],
    }),
  })
  if (!treeResponse.ok) {
    throw new Error(`Failed to create tree: ${treeResponse.status}`)
  }
  const treeData = await treeResponse.json<{ sha: string }>()

  // Create commit
  const newCommitResponse = await fetch(`${GITHUB_API}/repos/${owner}/${repo}/git/commits`, {
    method: "POST",
    headers: { ...headers, "Content-Type": "application/json" },
    body: JSON.stringify({
      message: commitMessage,
      tree: treeData.sha,
      parents: [baseCommitSha],
    }),
  })
  if (!newCommitResponse.ok) {
    throw new Error(`Failed to create commit: ${newCommitResponse.status}`)
  }
  const newCommitData = await newCommitResponse.json<{ sha: string }>()

  // Update ref
  const updateRefResponse = await fetch(
    `${GITHUB_API}/repos/${owner}/${repo}/git/refs/heads/${TRAILS_BRANCH}`,
    {
      method: "PATCH",
      headers: { ...headers, "Content-Type": "application/json" },
      body: JSON.stringify({ sha: newCommitData.sha }),
    },
  )
  if (!updateRefResponse.ok) {
    throw new Error(`Failed to update ref: ${updateRefResponse.status}`)
  }
}

export function updateTrailDiscussion(
