// ============================================================================
// CI/Checks Status
// ============================================================================

export interface BranchCheckStatus {
  /** Combined state: "success" | "failure" | "pending" | "none" */
  state: "success" | "failure" | "pending" | "none"
  /** Total number of checks/statuses */
  total_count: number
  /** Individual check details */
  checks: Array<{ name: string; status: string; conclusion: string | null }>
}

/**
 * Fetch the combined CI/checks status for a given commit ref.
 * Queries both the legacy commit status API and the newer check runs API,
 * then merges results into a unified status.
 */
export async function fetchCommitCheckStatus(
  repoFullName: string,
  ref: string,
  accessToken: string,
): Promise<BranchCheckStatus> {
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
    Authorization: `Bearer ${accessToken}`,
  }

  // Fetch both APIs in parallel
  const [statusRes, checkRunsRes] = await Promise.all([
    fetch(`${GITHUB_API}/repos/${repoFullName}/commits/${ref}/status`, { headers }),
    fetch(`${GITHUB_API}/repos/${repoFullName}/commits/${ref}/check-runs`, { headers }),
  ])

  const checks: Array<{ name: string; status: string; conclusion: string | null }> = []

  // Parse legacy commit statuses
  if (statusRes.ok) {
    const statusData = await statusRes.json<{
      state: string
      statuses: Array<{ context: string; state: string }>
    }>()
    for (const s of statusData.statuses) {
      checks.push({
        name: s.context,
        status: "completed",
        conclusion: s.state === "success" ? "success" : s.state === "pending" ? null : "failure",
      })
    }
  } else {
    statusRes.body?.cancel()
  }

  // Parse check runs
  if (checkRunsRes.ok) {
    const checkRunsData = await checkRunsRes.json<{
      total_count: number
      check_runs: Array<{ name: string; status: string; conclusion: string | null }>
    }>()
    for (const cr of checkRunsData.check_runs) {
      checks.push({
        name: cr.name,
        status: cr.status,
        conclusion: cr.conclusion,
      })
    }
  } else {
    checkRunsRes.body?.cancel()
  }

  if (checks.length === 0) {
    return { state: "none", total_count: 0, checks: [] }
  }

  // Determine combined state
  const hasFailure = checks.some(
    (c) =>
      c.conclusion === "failure" || c.conclusion === "timed_out" || c.conclusion === "cancelled",
  )
  const hasPending = checks.some((c) => c.status !== "completed" || c.conclusion === null)

  let state: BranchCheckStatus["state"]
  if (hasFailure) {
    state = "failure"
  } else if (hasPending) {
    state = "pending"
  } else {
    state = "success"
  }

  return { state, total_count: checks.length, checks }
}

// ============================================================================
// Branch Merging
// ============================================================================

/**
 * Merge a head branch into a base branch using GitHub's merge API.
 * This creates a merge commit directly without requiring a pull request.
 */
export async function mergeBranch(
  repoFullName: string,
  head: string,
  base: string,
  commitMessage: string,
  accessToken: string,
): Promise<{ sha: string }> {
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
    Authorization: `Bearer ${accessToken}`,
    "Content-Type": "application/json",
  }

  const response = await fetch(`${GITHUB_API}/repos/${repoFullName}/merges`, {
    method: "POST",
    headers,
    body: JSON.stringify({
      base,
      head,
      commit_message: commitMessage,
    }),
  })

  if (response.status === 409) {
    throw new Error("Merge conflict: the branches cannot be merged automatically")
  }

  if (response.status === 204) {
    // 204 means base already contains the head (nothing to merge)
    return { sha: "" }
  }

  if (!response.ok) {
    const text = await response.text()
    throw new Error(`Failed to merge ${head} into ${base}: ${response.status} - ${text}`)
  }

  const data = await response.json<{ sha: string }>()
  return { sha: data.sha }
}

/**
 * Delete a trail folder from the trails branch by removing all its files.
 * Uses GitHub Git API tree entries with sha=null to delete files.
 */
export async function deleteTrailFolder(
  repoFullName: string,
  trailId: string,
  accessToken: string,
  commitMessage: string,
): Promise<void> {
  const [owner, repo] = repoFullName.split("/")
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
    Authorization: `Bearer ${accessToken}`,
  }

  const prefix = `${trailId.slice(0, 2)}/${trailId.slice(2)}`
  const trailTree = await githubGraphQL<{
    repository: {
      object: {
        entries: Array<{
          name: string
          type: string
        }>
      } | null
    }
  }>(
    accessToken,
    `
      query TrailFolderEntries($owner: String!, $repo: String!, $expression: String!) {
        repository(owner: $owner, name: $repo) {
          object(expression: $expression) {
            ... on Tree {
              entries {
                name
                type
              }
            }
          }
        }
      }
    `,
    { owner, repo, expression: `${TRAILS_BRANCH}:${prefix}` },
  )

  const filesToDelete =
    trailTree.repository.object?.entries
      ?.filter((entry) => entry.type === "blob")
      .map((entry) => entry.name) ?? []

  if (filesToDelete.length === 0) {
    return
  }

  // Get current ref SHA
  const refResponse = await fetch(
    `${GITHUB_API}/repos/${owner}/${repo}/git/refs/heads/${TRAILS_BRANCH}`,
    { headers },
  )
  if (!refResponse.ok) {
    throw new Error(`Failed to get ref: ${refResponse.status}`)
  }
  const refData = await refResponse.json<{ object: { sha: string } }>()
  const baseCommitSha = refData.object.sha

  // Get base tree
  const commitResponse = await fetch(
    `${GITHUB_API}/repos/${owner}/${repo}/git/commits/${baseCommitSha}`,
    { headers },
  )
  if (!commitResponse.ok) {
    throw new Error(`Failed to get commit: ${commitResponse.status}`)
  }
  const commitData = await commitResponse.json<{ tree: { sha: string } }>()
  const baseTreeSha = commitData.tree.sha

  // Create tree with deletions (sha: null removes the file)
  const treeResponse = await fetch(`${GITHUB_API}/repos/${owner}/${repo}/git/trees`, {
    method: "POST",
    headers: { ...headers, "Content-Type": "application/json" },
    body: JSON.stringify({
      base_tree: baseTreeSha,
      tree: filesToDelete.map((fileName) => ({
        path: `${prefix}/${fileName}`,
        mode: "100644" as const,
        type: "blob" as const,
        sha: null,
      })),
    }),
  })
  if (!treeResponse.ok) {
    throw new Error(`Failed to create tree: ${treeResponse.status}`)
  }
  const treeData = await treeResponse.json<{ sha: string }>()

  // Create commit
  const newCommitResponse = await fetch(`${GITHUB_API}/repos/${owner}/${repo}/git/commits`, {
    method: "POST",
    headers: { ...headers, "Content-Type": "application/json" },
    body: JSON.stringify({
      message: commitMessage,
      tree: treeData.sha,
      parents: [baseCommitSha],
    }),
  })
  if (!newCommitResponse.ok) {
    throw new Error(`Failed to create commit: ${newCommitResponse.status}`)
  }
  const newCommitData = await newCommitResponse.json<{ sha: string }>()

  // Update ref
  const updateRefResponse = await fetch(
    `${GITHUB_API}/repos/${owner}/${repo}/git/refs/heads/${TRAILS_BRANCH}`,
    {
      method: "PATCH",
      headers: { ...headers, "Content-Type": "application/json" },
      body: JSON.stringify({ sha: newCommitData.sha }),
    },
  )
  if (!updateRefResponse.ok) {
    throw new Error(`Failed to update ref: ${updateRefResponse.status}`)
  }
}
// ============================================================================
// Branch Protection
// ============================================================================

export interface BranchProtectionCheck {
  protected: boolean
  /** null = indeterminate (insufficient permissions to read details) */
  has_required_pull_requests: boolean | null
  has_merge_queue: boolean | null
  has_required_status_checks: boolean | null
}

/**
 * Check whether a branch has protection rules that would prevent direct merging
 * (i.e. merging without a pull request).
 *
 * First checks the basic branch endpoint (accessible to all collaborators) to see
 * if the branch is protected at all. If it is, attempts the detailed protection
 * endpoint for specifics. If the detailed endpoint returns 403 (non-admin), returns
 * null for each rule since we cannot determine which are active.
 */
export async function fetchBranchProtection(
  repoFullName: string,
  branch: string,
  accessToken: string,
): Promise<BranchProtectionCheck> {
  const headers = githubHeaders(accessToken)

  // Step 1: Check if branch is protected at all (available to all collaborators)
  const branchRes = await fetch(
    `${GITHUB_API}/repos/${repoFullName}/branches/${encodeURIComponent(branch)}`,
    { headers },
  )

  if (!branchRes.ok) {
    branchRes.body?.cancel()
    return {
      protected: false,
      has_required_pull_requests: false,
      has_merge_queue: false,
      has_required_status_checks: false,
    }
  }

  const branchData = await branchRes.json<{ protected: boolean }>()
  if (!branchData.protected) {
    return {
      protected: false,
      has_required_pull_requests: false,
      has_merge_queue: false,
      has_required_status_checks: false,
    }
  }

  // Step 2: Fetch detailed protection rules (requires admin or push access)
  const protectionRes = await fetch(
    `${GITHUB_API}/repos/${repoFullName}/branches/${encodeURIComponent(branch)}/protection`,
    { headers },
  )

  if (!protectionRes.ok) {
    protectionRes.body?.cancel()
    // 403 = insufficient permissions; return indeterminate for specific rules
    return {
      protected: true,
      has_required_pull_requests: null,
      has_merge_queue: null,
      has_required_status_checks: null,
    }
  }

  const protection = await protectionRes.json<{
    required_pull_request_reviews?: unknown
    required_status_checks?: unknown
    required_linear_history?: { enabled: boolean }
  }>()

  return {
    protected: true,
    has_required_pull_requests: protection.required_pull_request_reviews != null,
    has_merge_queue: protection.required_linear_history?.enabled === true,
    has_required_status_checks: protection.required_status_checks != null,
  }
}

/**
 * Add a DEPRECATED_MOVED_TO_ENTIRE_STORAGE marker file to the root of the
 * trails orphan branch, signalling that trail metadata for this repo has been
 * migrated to the database.
 */
export async function addTrailsMigratedMarker(
  repoFullName: string,
  accessToken: string,
): Promise<void> {
  const [owner, repo] = repoFullName.split("/")
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
    Authorization: `Bearer ${accessToken}`,
  }

  // Get current ref SHA
  const refResponse = await fetch(
    `${GITHUB_API}/repos/${owner}/${repo}/git/refs/heads/${TRAILS_BRANCH}`,
    { headers },
  )
  if (!refResponse.ok) {
    throw new Error(`Failed to get trails branch ref: ${refResponse.status}`)
  }
  const refData = await refResponse.json<{ object: { sha: string } }>()
  const baseCommitSha = refData.object.sha

  // Get base tree
  const commitResponse = await fetch(
    `${GITHUB_API}/repos/${owner}/${repo}/git/commits/${baseCommitSha}`,
    { headers },
  )
  if (!commitResponse.ok) {
    throw new Error(`Failed to get commit: ${commitResponse.status}`)
  }
  const commitData = await commitResponse.json<{ tree: { sha: string } }>()
  const baseTreeSha = commitData.tree.sha

  // Create an empty blob
  const blobResponse = await fetch(`${GITHUB_API}/repos/${owner}/${repo}/git/blobs`, {
    method: "POST",
    headers: { ...headers, "Content-Type": "application/json" },
    body: JSON.stringify({ content: "", encoding: "utf-8" }),
  })
  if (!blobResponse.ok) {
    throw new Error(`Failed to create blob: ${blobResponse.status}`)
  }
  const blobData = await blobResponse.json<{ sha: string }>()

  // Create tree with marker file at root
  const treeResponse = await fetch(`${GITHUB_API}/repos/${owner}/${repo}/git/trees`, {
    method: "POST",
    headers: { ...headers, "Content-Type": "application/json" },
    body: JSON.stringify({
      base_tree: baseTreeSha,
      tree: [
        {
          path: "DEPRECATED_MOVED_TO_ENTIRE_STORAGE",
          mode: "100644",
          type: "blob",
          sha: blobData.sha,
        },
      ],
    }),
  })
  if (!treeResponse.ok) {
    throw new Error(`Failed to create tree: ${treeResponse.status}`)
  }
  const treeData = await treeResponse.json<{ sha: string }>()

  // Create commit
  const newCommitResponse = await fetch(`${GITHUB_API}/repos/${owner}/${repo}/git/commits`, {
    method: "POST",
    headers: { ...headers, "Content-Type": "application/json" },
    body: JSON.stringify({
      message: "chore: mark trails as migrated to database storage",
      tree: treeData.sha,
      parents: [baseCommitSha],
    }),
  })
  if (!newCommitResponse.ok) {
    throw new Error(`Failed to create commit: ${newCommitResponse.status}`)
  }
  const newCommitData = await newCommitResponse.json<{ sha: string }>()

  // Update ref
  const updateRefResponse = await fetch(
    `${GITHUB_API}/repos/${owner}/${repo}/git/refs/heads/${TRAILS_BRANCH}`,
    {
      method: "PATCH",
      headers: { ...headers, "Content-Type": "application/json" },
      body: JSON.stringify({ sha: newCommitData.sha }),
    },
  )
  if (!updateRefResponse.ok) {
    throw new Error(`Failed to update ref: ${updateRefResponse.status}`)
  }
}

