// GitHub API client

import type {
  GitHubUser,
  CachedRepos,
  CachedContributions,
  CachedFollowers,
  CachedStarred,
  CachedWatched,
  CachedPRs,
  CommitInfo,
  FileStats,
  CheckpointSummary,
  CommittedMetadata,
  SessionInfo,
  InitialAttribution,
} from "../types"
import { mapWithConcurrency } from "./concurrency"
import { CHECKPOINT_BRANCH, TRAILS_BRANCH, LEGACY_FALLBACK_AGENT_NAME } from "./constants"
import type {
  TrailMetadata,
  TrailDiscussion,
  TrailCheckpoints,
  TrailReviews,
  Trail,
} from "../types"
import { mapWithConcurrency } from "./concurrency"
import { CHECKPOINT_BRANCH, TRAILS_BRANCH } from "./constants"

const GITHUB_API = "https://api.github.com"

function githubHeaders(accessToken?: string): HeadersInit {
  return {
    Accept: "application/vnd.github+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
    ...(accessToken ? { Authorization: `Bearer ${accessToken}` } : {}),
  }
}

// Validation patterns for GraphQL query safety
const SHA_PATTERN = /^[a-f0-9]{40}$/i
const CHECKPOINT_ID_PATTERN = /^[a-f0-9]+$/i

function isValidSha(sha: string): boolean {
  return SHA_PATTERN.test(sha)
}

export function isValidCheckpointId(checkpointId: string): boolean {
  return (
    CHECKPOINT_ID_PATTERN.test(checkpointId) &&
    checkpointId.length >= 4 &&
    checkpointId.length <= 64
  )
}

// Branch name validation: alphanumeric, dots, underscores, hyphens, slashes
// Max length 256 to match Git's REFNAME_MAX limit
const BRANCH_NAME_PATTERN = /^[A-Za-z0-9._/-]+$/
const MAX_BRANCH_NAME_LENGTH = 256

export function isValidBranchName(branch: string): boolean {
  if (!branch || branch.length > MAX_BRANCH_NAME_LENGTH) {
    return false
  }
  return BRANCH_NAME_PATTERN.test(branch)
}

// GitHub organization name validation
const GITHUB_ORG_NAME_PATTERN = /^[a-zA-Z0-9]([a-zA-Z0-9-]{0,37}[a-zA-Z0-9])?$/
const MAX_ORG_NAME_LENGTH = 39

export function isValidGitHubOrgName(orgName: string): boolean {
  if (!orgName || orgName.length > MAX_ORG_NAME_LENGTH) {
    return false
  }
  return GITHUB_ORG_NAME_PATTERN.test(orgName)
}

interface TokenResponse {
  access_token: string
  token_type: string
  scope: string
  refresh_token?: string
  expires_in?: number // seconds until access_token expires (typically 28800 = 8 hours)
  refresh_token_expires_in?: number // seconds until refresh_token expires (typically 6 months)
}

// Sleep utility for retry delays
function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms))
}

// Retry configuration
const RETRY_CONFIG = {
  maxAttempts: 3,
  retryableStatuses: [502, 503, 504, 429], // Bad Gateway, Service Unavailable, Gateway Timeout, Rate Limited
  getBackoffDelay: (attempt: number) => Math.pow(2, attempt) * 1000, // 1s, 2s, 4s
}

// Fetch with exponential backoff retry for transient errors
async function fetchWithRetry(
  url: string,
  options: RequestInit,
  retryConfig = RETRY_CONFIG,
): Promise<Response> {
  let lastError: Error | null = null

  for (let attempt = 0; attempt < retryConfig.maxAttempts; attempt++) {
    try {
      const response = await fetch(url, options)

      // If response is successful or not retryable, return it
      if (response.ok || !retryConfig.retryableStatuses.includes(response.status)) {
        return response
      }

      // For retryable errors, cancel body and retry if not last attempt
      if (attempt < retryConfig.maxAttempts - 1) {
        response.body?.cancel()
        const delay = retryConfig.getBackoffDelay(attempt)
        console.warn(
          `GitHub API returned ${response.status}, retrying in ${delay}ms (attempt ${attempt + 1}/${retryConfig.maxAttempts})`,
        )
        await sleep(delay)
        continue
      }

      // Last attempt with retryable error - return the response
      return response
    } catch (error) {
      lastError = error instanceof Error ? error : new Error(String(error))

      // Network errors - retry if not last attempt
      if (attempt < retryConfig.maxAttempts - 1) {
        const delay = retryConfig.getBackoffDelay(attempt)
        console.warn(
          `GitHub API request failed: ${lastError.message}, retrying in ${delay}ms (attempt ${attempt + 1}/${retryConfig.maxAttempts})`,
        )
        await sleep(delay)
        continue
      }
    }
  }

  // All retries exhausted
  throw lastError || new Error("All retry attempts failed")
}

// Exchange OAuth code for access token
export async function exchangeCodeForToken(
  code: string,
  clientId: string,
  clientSecret: string,
  redirectUri: string,
): Promise<TokenResponse> {
  const response = await fetchWithRetry("https://github.com/login/oauth/access_token", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Accept: "application/json",
    },
    body: JSON.stringify({
      client_id: clientId,
      client_secret: clientSecret,
      code,
      redirect_uri: redirectUri,
    }),
  })

  if (!response.ok) {
    // Cancel the response body to avoid stalled connections in Workers
    response.body?.cancel()
    throw new Error(`GitHub token exchange failed: ${response.status}`)
  }

  const data = await response.json<TokenResponse & { error?: string }>()

  if (data.error) {
    throw new Error(`GitHub OAuth error: ${data.error}`)
  }

  if (!data.access_token) {
    throw new Error("GitHub token exchange returned empty access_token")
  }

  return data
}

// Refresh an expired access token using a refresh token
export async function refreshAccessToken(
  refreshToken: string,
  clientId: string,
  clientSecret: string,
): Promise<TokenResponse> {
  const response = await fetchWithRetry("https://github.com/login/oauth/access_token", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Accept: "application/json",
    },
    body: JSON.stringify({
      client_id: clientId,
      client_secret: clientSecret,
      grant_type: "refresh_token",
      refresh_token: refreshToken,
    }),
  })

  if (!response.ok) {
    // Cancel the response body to avoid stalled connections in Workers
    response.body?.cancel()
    throw new Error(`GitHub token refresh failed: ${response.status}`)
  }

  const data = await response.json<TokenResponse & { error?: string; error_description?: string }>()

  if (data.error) {
    throw new Error(`GitHub token refresh error: ${data.error} - ${data.error_description}`)
  }

  return data
}

// --- GraphQL Client ---

const GITHUB_GRAPHQL = "https://api.github.com/graphql"

interface GraphQLResponse<T> {
  data?: T
  errors?: Array<{ message: string; path?: string[] }>
}

// Custom error class for rate limit detection
export class GitHubRateLimitError extends Error {
  constructor(
    message: string,
    public readonly status: number,
    public readonly resetAt?: number,
  ) {
    super(message)
    this.name = "GitHubRateLimitError"
  }
}

// Result type for GraphQL calls that may have partial data
export interface GraphQLResult<T> {
  data: T | null
  errors: Array<{ message: string; path?: string[] }>
  hasPartialData: boolean
}

// Check if a response indicates rate limiting (429 or 403 with rate limit headers)
function isRateLimited(response: Response): { limited: boolean; resetAt?: number } {
  if (response.status === 429) {
    const resetHeader = response.headers.get("X-RateLimit-Reset")
    return { limited: true, resetAt: resetHeader ? parseInt(resetHeader, 10) : undefined }
  }

  if (response.status === 403) {
    const remaining = response.headers.get("X-RateLimit-Remaining")
    if (remaining === "0") {
      const resetHeader = response.headers.get("X-RateLimit-Reset")
      return { limited: true, resetAt: resetHeader ? parseInt(resetHeader, 10) : undefined }
    }
  }

  return { limited: false }
}

// GraphQL call that throws on errors (original behavior for backwards compatibility)
export async function githubGraphQL<T>(
  token: string,
  query: string,
  variables: Record<string, unknown> = {},
): Promise<T> {
  const response = await fetch(GITHUB_GRAPHQL, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json",
      "User-Agent": "entire-api",
    },
    body: JSON.stringify({ query, variables }),
  })

  // Check for rate limiting (429 or 403 with X-RateLimit-Remaining: 0)
  const rateLimitCheck = isRateLimited(response)
  if (rateLimitCheck.limited) {
    // Cancel the response body to avoid stalled connections in Workers
    response.body?.cancel()
    throw new GitHubRateLimitError(
      "GitHub API rate limit exceeded",
      response.status,
      rateLimitCheck.resetAt,
    )
  }

  if (!response.ok) {
    // Cancel the response body to avoid stalled connections in Workers
    response.body?.cancel()
    throw new Error(`GitHub GraphQL error: ${response.status}`)
  }

  const result = await response.json<GraphQLResponse<T>>()

  if (result.errors && result.errors.length > 0) {
    const errorMessages = result.errors.map((e) => e.message).join(", ")
    throw new Error(`GitHub GraphQL errors: ${errorMessages}`)
  }

  if (!result.data) {
    throw new Error("GitHub GraphQL returned no data")
  }

  return result.data
}

// GraphQL call that returns partial data when available (for batch operations)
// Returns data even if some errors occurred, allowing partial success handling
export async function githubGraphQLPartial<T>(
  token: string,
  query: string,
  variables: Record<string, unknown> = {},
): Promise<GraphQLResult<T>> {
  const response = await fetch(GITHUB_GRAPHQL, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json",
      "User-Agent": "entire-api",
    },
    body: JSON.stringify({ query, variables }),
  })

  // Check for rate limiting (429 or 403 with X-RateLimit-Remaining: 0)
  const rateLimitCheck = isRateLimited(response)
  if (rateLimitCheck.limited) {
    // Cancel the response body to avoid stalled connections in Workers
    response.body?.cancel()
    throw new GitHubRateLimitError(
      "GitHub API rate limit exceeded",
      response.status,
      rateLimitCheck.resetAt,
    )
  }

  if (!response.ok) {
    // Cancel the response body to avoid stalled connections in Workers
    response.body?.cancel()
    throw new Error(`GitHub GraphQL error: ${response.status}`)
  }

  const result = await response.json<GraphQLResponse<T>>()

  return {
    data: result.data ?? null,
    errors: result.errors ?? [],
    hasPartialData:
      result.data !== undefined && result.errors !== undefined && result.errors.length > 0,
  }
}

// Batch result type for tracking partial failures
export interface BatchResult<T> {
  data: Map<string, T>
  failedItems: string[]
  errors: string[]
}

// Commit stats with optional per-file breakdown.
// `files` is null when stats were fetched via GraphQL (which doesn't provide per-file data).
// The DB upsert uses COALESCE on file_stats, so null preserves any existing per-file data.
export interface CommitStats {
  additions: number
  deletions: number
  filesChanged: number
  files: FileStats[] | null
}

// Patch size limits to prevent storing massive diffs
const MAX_PATCH_SIZE_PER_FILE = 50 * 1024 // 50KB per file
const MAX_TOTAL_PATCH_SIZE = 500 * 1024 // 500KB total per commit

/** Shared helper to apply patch size limits across a list of files. */
export function applyPatchLimits(
  rawFiles: Array<{
    filename: string
    status: string
    additions: number
    deletions: number
    patch?: string
  }>,
): FileStats[] {
  let totalPatchSize = 0

  return rawFiles.map((f) => {
    let patch: string | null = null
    let patchTruncated: boolean | undefined

    if (f.patch) {
      const patchSize = f.patch.length

      if (patchSize > MAX_PATCH_SIZE_PER_FILE) {
        if (totalPatchSize + MAX_PATCH_SIZE_PER_FILE > MAX_TOTAL_PATCH_SIZE) {
          patch = null
          patchTruncated = true
        } else {
          patch = f.patch.slice(0, MAX_PATCH_SIZE_PER_FILE) + "\n... [truncated]"
          patchTruncated = true
          totalPatchSize += MAX_PATCH_SIZE_PER_FILE
        }
      } else if (totalPatchSize + patchSize > MAX_TOTAL_PATCH_SIZE) {
        patch = null
        patchTruncated = true
      } else {
        patch = f.patch
        totalPatchSize += patchSize
      }
    }

    return {
      filename: f.filename,
      status: f.status as FileStats["status"],
      additions: f.additions,
      deletions: f.deletions,
      patch,
      patchTruncated,
    }
  })
}

// Batch fetch commit stats using REST API
// Returns a map of SHA -> { additions, deletions, filesChanged, files[] } along with any failures
// Uses REST API instead of GraphQL to get per-file breakdown
export async function fetchCommitStatsBatch(
  repoFullName: string,
  shas: string[],
  token: string,
): Promise<BatchResult<CommitStats>> {
  const results: BatchResult<CommitStats> = {
    data: new Map(),
    failedItems: [],
    errors: [],
  }

  // Filter to valid SHAs
  const invalidShas: string[] = []
  const validShas = shas.filter((sha) => {
    if (!isValidSha(sha)) {
      console.warn(`[github-rest] Skipping invalid SHA: ${sha.slice(0, 10)}...`)
      invalidShas.push(sha)
      return false
    }
    return true
  })

  // Track invalid SHAs as failed items
  results.failedItems.push(...invalidShas)

  if (validShas.length === 0) return results

  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
    Authorization: `Bearer ${token}`,
  }

  // Fetch commits with controlled concurrency to avoid rate limits
  // REST API: 1 request per commit (unlike GraphQL batch)
  const CONCURRENCY = 10

  const fetchOne = async (
    sha: string,
  ): Promise<{ sha: string; stats: CommitStats | null; error?: string }> => {
    try {
      const response = await fetch(`${GITHUB_API}/repos/${repoFullName}/commits/${sha}`, {
        headers,
      })

      // Check for rate limiting
      const rateLimitCheck = isRateLimited(response)
      if (rateLimitCheck.limited) {
        response.body?.cancel()
        throw new GitHubRateLimitError(
          "GitHub API rate limit exceeded",
          response.status,
          rateLimitCheck.resetAt,
        )
      }

      if (!response.ok) {
        response.body?.cancel()
        return { sha, stats: null, error: `HTTP ${response.status}` }
      }

      const data = await response.json<{
        files?: Array<{
          filename: string
          status: string
          additions: number
          deletions: number
          patch?: string
        }>
        stats?: {
          additions: number
          deletions: number
          total: number
        }
      }>()

      const files = applyPatchLimits(data.files ?? [])

      // Use stats field for accurate totals (files array is truncated to ~300 entries for large commits)
      const additions = data.stats?.additions ?? 0
      const deletions = data.stats?.deletions ?? 0

      return {
        sha,
        stats: {
          additions,
          deletions,
          filesChanged: files.length,
          files,
        },
      }
    } catch (err) {
      // Re-throw rate limit errors
      if (err instanceof GitHubRateLimitError) {
        throw err
      }
      return { sha, stats: null, error: err instanceof Error ? err.message : String(err) }
    }
  }

  // Process in batches with controlled concurrency
  for (let i = 0; i < validShas.length; i += CONCURRENCY) {
    const batch = validShas.slice(i, i + CONCURRENCY)

    try {
      const batchResults = await Promise.all(batch.map(fetchOne))

      for (const result of batchResults) {
        if (result.stats) {
          results.data.set(result.sha, result.stats)
        } else {
          results.failedItems.push(result.sha)
          if (result.error) {
            results.errors.push(`${result.sha.slice(0, 7)}: ${result.error}`)
          }
        }
      }
    } catch (err) {
      // Rate limit error - stop processing and re-throw
      if (err instanceof GitHubRateLimitError) {
        throw err
      }
      // Other errors - mark remaining batch as failed
      const errorMsg = err instanceof Error ? err.message : String(err)
      console.error(`[github-rest] Failed to fetch commit stats batch:`, errorMsg)
      results.failedItems.push(...batch)
      results.errors.push(`Batch ${Math.floor(i / CONCURRENCY) + 1}: ${errorMsg}`)
    }
  }

  return results
}

// Batch fetch commit summary stats using GraphQL (additions, deletions, changedFiles).
// Much more efficient than REST: ~100 commits per query instead of 1 per request.
// Does NOT return per-file breakdowns — use fetchCommitStatsBatch for that.
export async function fetchCommitGraphQLStatsBatch(
  repoFullName: string,
  shas: string[],
  token: string,
): Promise<BatchResult<CommitStats>> {
  const results: BatchResult<CommitStats> = {
    data: new Map(),
    failedItems: [],
    errors: [],
  }

  const validShas = shas.filter((sha) => {
    if (!isValidSha(sha)) {
      results.failedItems.push(sha)
      return false
    }
    return true
  })

  if (validShas.length === 0) return results

  const [owner, repo] = repoFullName.split("/")
  const SHAS_PER_BATCH = 100

  for (let i = 0; i < validShas.length; i += SHAS_PER_BATCH) {
    const batch = validShas.slice(i, i + SHAS_PER_BATCH)

    // Build aliased GraphQL query: c0: object(expression: "sha") { ... on Commit { ... } }
    const fragments = batch
      .map(
        (sha, idx) =>
          `c${idx}: object(expression: "${sha}") { ... on Commit { additions deletions changedFilesIfAvailable } }`,
      )
      .join("\n      ")

    const query = `
      query($owner: String!, $repo: String!) {
        repository(owner: $owner, name: $repo) {
          ${fragments}
        }
      }
    `

    try {
      const result = await githubGraphQLPartial<{
        repository: Record<
          string,
          { additions: number; deletions: number; changedFilesIfAvailable: number | null } | null
        >
      }>(token, query, { owner, repo })

      if (result.data?.repository) {
        for (let idx = 0; idx < batch.length; idx++) {
          const commit = result.data.repository[`c${idx}`]
          if (commit) {
            results.data.set(batch[idx], {
              additions: commit.additions,
              deletions: commit.deletions,
              filesChanged: commit.changedFilesIfAvailable ?? 0,
              files: null, // per-file breakdown not available via GraphQL; null preserves existing DB data
            })
          } else {
            results.failedItems.push(batch[idx])
          }
        }
      } else if (result.errors.length > 0) {
        const errorMsg = result.errors.map((e) => e.message).join(", ")
        console.error(`[github-graphql] Failed to fetch commit stats batch:`, errorMsg)
        results.failedItems.push(...batch)
        results.errors.push(`Batch ${Math.floor(i / SHAS_PER_BATCH) + 1}: ${errorMsg}`)
      }
    } catch (err) {
      if (err instanceof GitHubRateLimitError) throw err
      const errorMsg = err instanceof Error ? err.message : String(err)
      console.error(`[github-graphql] Failed to fetch commit stats batch:`, errorMsg)
      results.failedItems.push(...batch)
      results.errors.push(`Batch ${Math.floor(i / SHAS_PER_BATCH) + 1}: ${errorMsg}`)
    }
  }

  return results
}

// Batch fetch session data (metadata.json and prompt.txt) using GraphQL
// Returns a map of checkpointId -> { prompt, metadata } along with any failures
export interface SessionData {
  prompt: string | null
  agent: string
  steps: number
  sessionCount: number
  strategy: string | null
  createdAt: string
  branch: string | null // Branch where checkpoint was created (from metadata.json)
  // Additional metadata fields
  sessionId: string | null
  filesTouched: string[] | null
  sessionIds: string[] | null
  transcriptUuidAtStart: string | null
  /** @deprecated Use checkpointTranscriptStart instead */
  transcriptLinesAtStart: number | null
  checkpointTranscriptStart: number | null
  // Token usage metrics (aggregated across all sessions)
  inputTokens: number | null
  cacheCreationTokens: number | null
  cacheReadTokens: number | null
  outputTokens: number | null
  apiCallCount: number | null
  // Attribution metrics
  attributionAgentLines: number | null
  attributionHumanAdded: number | null
  attributionHumanModified: number | null
  attributionHumanRemoved: number | null
  attributionTotalCommitted: number | null
  attributionAgentPercentage: number | null
  attributionCalculatedAt: string | null
  // V1: Per-session details array
  sessions: SessionInfo[] | null
}

/**
 * Map an InitialAttribution (snake_case JSON) to the camelCase shape used internally.
 */
function mapAttribution(a: InitialAttribution): SessionInfo["attribution"] {
  return {
    calculatedAt: a.calculated_at,
    agentLines: a.agent_lines,
    humanAdded: a.human_added,
    humanModified: a.human_modified,
    humanRemoved: a.human_removed,
    totalCommitted: a.total_committed,
    agentPercentage: a.agent_percentage,
  }
}

/**
 * Parse a CommittedMetadata JSON into a SessionInfo object
 */
export function parseSessionMetadata(
  metadataText: string,
  promptText: string | null,
): SessionInfo | null {
  try {
    const parsed: CommittedMetadata = JSON.parse(metadataText)
    const tokenUsage = parsed.token_usage
    const attribution = parsed.initial_attribution

    return {
      prompt: promptText?.split("\n")[0] ?? null,
      agent: parsed.agent ?? LEGACY_FALLBACK_AGENT_NAME,
      steps: parsed.checkpoints_count ?? 1,
      sessionId: parsed.session_id,
      createdAt: parsed.created_at,
      isTask: parsed.is_task,
      toolUseId: parsed.tool_use_id,
      transcriptIdentifierAtStart: parsed.transcript_identifier_at_start,
      checkpointTranscriptStart:
        parsed.checkpoint_transcript_start ?? parsed.transcript_lines_at_start,
      summary: parsed.summary,
      tokenUsage: tokenUsage
        ? {
            inputTokens: tokenUsage.input_tokens,
            cacheCreationTokens: tokenUsage.cache_creation_tokens,
            cacheReadTokens: tokenUsage.cache_read_tokens,
            outputTokens: tokenUsage.output_tokens,
            apiCallCount: tokenUsage.api_call_count,
          }
        : undefined,
      attribution: attribution ? mapAttribution(attribution) : undefined,
    }
  } catch {
    return null
  }
}

/**
 * Aggregate multiple SessionInfo objects into a single SessionData
 * Used for v1 format where each checkpoint has multiple sessions
 */
export function aggregateSessionsToSessionData(
  sessions: SessionInfo[],
  rootSummary: CheckpointSummary | null,
  branch: string | null,
): SessionData {
  if (sessions.length === 0) {
    return createDefaultSessionData()
  }

  // Latest session (last in array) is used for agent, prompt, summary
  const latestSession = sessions[sessions.length - 1]

  // Sum token usage across all sessions
  let inputTokens = 0
  let cacheCreationTokens = 0
  let cacheReadTokens = 0
  let outputTokens = 0
  let apiCallCount = 0
  let hasTokenUsage = false

  for (const session of sessions) {
    if (session.tokenUsage) {
      hasTokenUsage = true
      inputTokens += session.tokenUsage.inputTokens ?? 0
      cacheCreationTokens += session.tokenUsage.cacheCreationTokens ?? 0
      cacheReadTokens += session.tokenUsage.cacheReadTokens ?? 0
      outputTokens += session.tokenUsage.outputTokens ?? 0
      apiCallCount += session.tokenUsage.apiCallCount ?? 0
    }
  }

  // Multi-session checkpoints aggregate attribution across all sessions into combined_attribution.
  // Prefer it so that token counts and percentages reflect the full checkpoint, not just the final
  // session. Fall back to the latest session's attribution for single-session checkpoints, which
  // never populate combined_attribution, and for old checkpoints written before this field existed.
  const resolvedAttribution = rootSummary?.combined_attribution
    ? mapAttribution(rootSummary.combined_attribution)
    : latestSession.attribution

  // Calculate total steps across all sessions
  const totalSteps = sessions.reduce((sum, s) => sum + (s.steps ?? 1), 0)

  return {
    prompt: latestSession.prompt,
    agent: latestSession.agent,
    steps: totalSteps,
    sessionCount: sessions.length,
    strategy: rootSummary?.strategy ?? null,
    createdAt: sessions[0].createdAt ?? new Date().toISOString(),
    branch,
    sessionId: latestSession.sessionId ?? null,
    filesTouched: rootSummary?.files_touched ?? null,
    sessionIds: sessions.map((s) => s.sessionId).filter((id): id is string => id != null),
    transcriptUuidAtStart: latestSession.transcriptIdentifierAtStart ?? null,
    transcriptLinesAtStart: latestSession.checkpointTranscriptStart ?? null,
    checkpointTranscriptStart: latestSession.checkpointTranscriptStart ?? null,
    inputTokens: hasTokenUsage ? inputTokens : null,
    cacheCreationTokens: hasTokenUsage ? cacheCreationTokens : null,
    cacheReadTokens: hasTokenUsage ? cacheReadTokens : null,
    outputTokens: hasTokenUsage ? outputTokens : null,
    apiCallCount: hasTokenUsage ? apiCallCount : null,
    attributionAgentLines: resolvedAttribution?.agentLines ?? null,
    attributionHumanAdded: resolvedAttribution?.humanAdded ?? null,
    attributionHumanModified: resolvedAttribution?.humanModified ?? null,
    attributionHumanRemoved: resolvedAttribution?.humanRemoved ?? null,
    attributionTotalCommitted: resolvedAttribution?.totalCommitted ?? null,
    attributionAgentPercentage: resolvedAttribution?.agentPercentage ?? null,
    attributionCalculatedAt: resolvedAttribution?.calculatedAt ?? null,
    sessions,
  }
}

/**
 * Create default SessionData for checkpoints with no data
 */
function createDefaultSessionData(): SessionData {
  return {
    prompt: null,
    agent: LEGACY_FALLBACK_AGENT_NAME,
    steps: 1,
    sessionCount: 1,
    strategy: null,
    createdAt: new Date().toISOString(),
    branch: null,
    sessionId: null,
    filesTouched: null,
    sessionIds: null,
    transcriptUuidAtStart: null,
    transcriptLinesAtStart: null,
    checkpointTranscriptStart: null,
    inputTokens: null,
    cacheCreationTokens: null,
    cacheReadTokens: null,
    outputTokens: null,
    apiCallCount: null,
    attributionAgentLines: null,
    attributionHumanAdded: null,
    attributionHumanModified: null,
    attributionHumanRemoved: null,
    attributionTotalCommitted: null,
    attributionAgentPercentage: null,
    attributionCalculatedAt: null,
    sessions: null,
  }
}

/**
 * Fetch session data for v1 format checkpoints using optimistic fetching.
 *
 * V1 format structure:
 * - Root metadata.json = CheckpointSummary (has sessions[] array with file paths)
 * - Each session in 0/, 1/, 2/, etc. folders with metadata.json and prompt.txt
 *
 * Optimistic fetch strategy:
 * 1. Batch fetches root + first 2 sessions (most checkpoints have 1-2 sessions)
 * 2. GraphQL returns null for non-existent files (no error)
 * 3. Follow-up fetch only for checkpoints with 3+ sessions (rare)
 */
export async function fetchSessionDataBatch(
  repoFullName: string,
  checkpointIds: string[],
  token: string,
): Promise<BatchResult<SessionData>> {
  const results: BatchResult<SessionData> = {
    data: new Map(),
    failedItems: [],
    errors: [],
  }

  // Filter to valid checkpoint IDs to prevent GraphQL injection
  const invalidIds: string[] = []
  const validCheckpointIds = checkpointIds.filter((id) => {
    if (!isValidCheckpointId(id)) {
      console.warn(`[github-graphql] Skipping invalid checkpoint ID: ${id.slice(0, 10)}...`)
      invalidIds.push(id)
      return false
    }
    return true
  })

  // Track invalid IDs as failed items
  results.failedItems.push(...invalidIds)

  if (validCheckpointIds.length === 0) return results

  const [owner, repo] = repoFullName.split("/")

  // Track checkpoints that need follow-up fetches (>2 sessions)
  const needsFollowUp: Array<{ checkpointId: string; sessionCount: number; folderPath: string }> =
    []

  // Intermediate storage for parsed data before aggregation
  const parsedRoots = new Map<string, CheckpointSummary | null>()
  const parsedSessions = new Map<string, (SessionInfo | null)[]>()

  // Each checkpoint fetches 5 files (root metadata + 2 sessions * (metadata + prompt))
  // so 10 checkpoints = 50 file objects per GraphQL query
  const CHECKPOINTS_PER_BATCH = 10

  for (let i = 0; i < validCheckpointIds.length; i += CHECKPOINTS_PER_BATCH) {
    const batch = validCheckpointIds.slice(i, i + CHECKPOINTS_PER_BATCH)

    // Build dynamic query with aliases for each checkpoint's files
    // Optimistically fetch root + first 2 sessions
    const fileQueries = batch
      .map((checkpointId, idx) => {
        const folderPath = `${checkpointId.slice(0, 2)}/${checkpointId.slice(2)}`
        return `
          c${idx}_root: object(expression: "${CHECKPOINT_BRANCH}:${folderPath}/metadata.json") { ... on Blob { text } }
          c${idx}_s0_meta: object(expression: "${CHECKPOINT_BRANCH}:${folderPath}/0/metadata.json") { ... on Blob { text } }
          c${idx}_s0_prompt: object(expression: "${CHECKPOINT_BRANCH}:${folderPath}/0/prompt.txt") { ... on Blob { text } }
          c${idx}_s1_meta: object(expression: "${CHECKPOINT_BRANCH}:${folderPath}/1/metadata.json") { ... on Blob { text } }
          c${idx}_s1_prompt: object(expression: "${CHECKPOINT_BRANCH}:${folderPath}/1/prompt.txt") { ... on Blob { text } }
        `
      })
      .join("\n")

    const query = `
      query SessionDataV1($owner: String!, $repo: String!) {
        repository(owner: $owner, name: $repo) {
          ${fileQueries}
        }
      }
    `

    try {
      const result = await githubGraphQLPartial<{
        repository: Record<string, { text: string } | null>
      }>(token, query, { owner, repo })

      if (result.hasPartialData) {
        console.warn(
          `[github-graphql] Partial success in v1 session data batch:`,
          result.errors.map((e) => e.message).join(", "),
        )
      }

      if (result.data?.repository) {
        for (let idx = 0; idx < batch.length; idx++) {
          const checkpointId = batch[idx]
          const folderPath = `${checkpointId.slice(0, 2)}/${checkpointId.slice(2)}`
          const repoData = result.data.repository

          const rootMetadata = repoData[`c${idx}_root`]
          const s0Meta = repoData[`c${idx}_s0_meta`]
          const s0Prompt = repoData[`c${idx}_s0_prompt`]
          const s1Meta = repoData[`c${idx}_s1_meta`]
          const s1Prompt = repoData[`c${idx}_s1_prompt`]

          // Parse root CheckpointSummary
          let rootSummary: CheckpointSummary | null = null
          if (rootMetadata?.text) {
            try {
              rootSummary = JSON.parse(rootMetadata.text) as CheckpointSummary
            } catch {
              // Invalid JSON
            }
          }
          parsedRoots.set(checkpointId, rootSummary)

          // Parse sessions we fetched (use explicit indices to maintain ordering)
          // Store sessions with index positions preserved (nulls indicate missing sessions)
          // Don't filter here - follow-up fetch uses indices, and aggregation handles nulls
          const sessions: (SessionInfo | null)[] = []
          sessions[0] = s0Meta?.text
            ? parseSessionMetadata(s0Meta.text, s0Prompt?.text ?? null)
            : null
          sessions[1] = s1Meta?.text
            ? parseSessionMetadata(s1Meta.text, s1Prompt?.text ?? null)
            : null
          parsedSessions.set(checkpointId, sessions)

          // Check if we need follow-up (root tells us actual session count)
          const actualSessionCount =
            rootSummary?.sessions?.length ?? sessions.filter(Boolean).length
          if (actualSessionCount > 2) {
            needsFollowUp.push({ checkpointId, sessionCount: actualSessionCount, folderPath })
          }
        }
      } else if (result.errors.length > 0) {
        const errorMsg = result.errors.map((e) => e.message).join(", ")
        console.error(`[github-graphql] Failed to fetch v1 session data batch:`, errorMsg)
        results.failedItems.push(...batch)
        results.errors.push(`Batch ${i / CHECKPOINTS_PER_BATCH + 1}: ${errorMsg}`)
      }
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : String(err)
      console.error(`[github-graphql] Failed to fetch v1 session data batch:`, errorMsg)
      results.failedItems.push(...batch)
      results.errors.push(`Batch ${i / CHECKPOINTS_PER_BATCH + 1}: ${errorMsg}`)
    }
  }

  // Follow-up fetch for checkpoints with 3+ sessions
  if (needsFollowUp.length > 0) {
    console.log(
      `[github-graphql] Follow-up fetch for ${needsFollowUp.length} checkpoints with >2 sessions`,
    )

    // Build query for sessions 2+ for each checkpoint that needs it
    const followUpQueries: string[] = []
    const followUpMapping: Array<{
      checkpointId: string
      sessionIdx: number
      aliasPrefix: string
    }> = []

    for (const { checkpointId, sessionCount, folderPath } of needsFollowUp) {
      for (let sessionIdx = 2; sessionIdx < sessionCount; sessionIdx++) {
        const aliasPrefix = `f${followUpMapping.length}`
        followUpQueries.push(`
          ${aliasPrefix}_meta: object(expression: "${CHECKPOINT_BRANCH}:${folderPath}/${sessionIdx}/metadata.json") { ... on Blob { text } }
          ${aliasPrefix}_prompt: object(expression: "${CHECKPOINT_BRANCH}:${folderPath}/${sessionIdx}/prompt.txt") { ... on Blob { text } }
        `)
        followUpMapping.push({ checkpointId, sessionIdx, aliasPrefix })
      }
    }

    if (followUpQueries.length > 0) {
      const followUpQuery = `
        query SessionDataV1FollowUp($owner: String!, $repo: String!) {
          repository(owner: $owner, name: $repo) {
            ${followUpQueries.join("\n")}
          }
        }
      `

      try {
        const followUpResult = await githubGraphQLPartial<{
          repository: Record<string, { text: string } | null>
        }>(token, followUpQuery, { owner, repo })

        if (followUpResult.data?.repository) {
          for (const { checkpointId, sessionIdx, aliasPrefix } of followUpMapping) {
            const metaText = followUpResult.data.repository[`${aliasPrefix}_meta`]?.text
            const promptText = followUpResult.data.repository[`${aliasPrefix}_prompt`]?.text

            if (metaText) {
              const sessions = parsedSessions.get(checkpointId) ?? []
              // Ensure array is long enough
              while (sessions.length < sessionIdx) {
                sessions.push(null)
              }
              sessions[sessionIdx] = parseSessionMetadata(metaText, promptText ?? null)
              parsedSessions.set(checkpointId, sessions)
            }
          }
        }
      } catch (err) {
        const errorMsg = err instanceof Error ? err.message : String(err)
        console.warn(`[github-graphql] Follow-up fetch failed:`, errorMsg)
        // Don't fail the whole batch - we still have partial data from first fetch
      }
    }
  }

  // Aggregate all parsed data into SessionData results
  for (const checkpointId of validCheckpointIds) {
    if (results.failedItems.includes(checkpointId)) continue

    const rootSummary = parsedRoots.get(checkpointId) ?? null
    const sessions = (parsedSessions.get(checkpointId) ?? []).filter(
      (s): s is SessionInfo => s !== null,
    )

    const branch = rootSummary?.branch ?? null
    const sessionData = aggregateSessionsToSessionData(sessions, rootSummary, branch)

    results.data.set(checkpointId, sessionData)
  }

  return results
}

// Get authenticated GitHub user
export async function getGitHubUser(accessToken: string): Promise<GitHubUser> {
  const response = await fetch(`${GITHUB_API}/user`, {
    headers: {
      Authorization: `Bearer ${accessToken}`,
      Accept: "application/vnd.github+json",
      "User-Agent": "gh-social-api",
      "X-GitHub-Api-Version": "2022-11-28",
    },
  })

  if (!response.ok) {
    // Cancel the response body to avoid stalled connections in Workers
    response.body?.cancel()
    throw new Error(`GitHub API error: ${response.status}`)
  }

  return response.json<GitHubUser>()
}

// Raw GitHub repo response type
export interface GitHubRepoRaw {
  id: number
  name: string
  full_name: string
  description: string | null
  html_url: string
  stargazers_count: number
  language: string | null
  fork: boolean
  archived: boolean
  private: boolean
  updated_at: string
  pushed_at: string | null
  default_branch: string
  permissions?: {
    admin: boolean
    maintain: boolean
    push: boolean
    triage: boolean
    pull: boolean
  }
}

// Convert GitHub permissions to a single permission level
export function getPermissionLevel(
  permissions?: GitHubRepoRaw["permissions"],
): "admin" | "maintain" | "write" | "triage" | "read" {
  if (!permissions) return "read"
  if (permissions.admin) return "admin"
  if (permissions.maintain) return "maintain"
  if (permissions.push) return "write"
  if (permissions.triage) return "triage"
  return "read"
}

// Fetch user's repositories with all data (for syncing to DB)
// Paginates through all pages (max 10 pages = 1000 repos to avoid runaway requests)
export async function fetchUserReposWithForks(
  username: string,
  accessToken?: string,
): Promise<GitHubRepoRaw[]> {
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "gh-social-api",
    "X-GitHub-Api-Version": "2022-11-28",
  }

  if (accessToken) {
    headers.Authorization = `Bearer ${accessToken}`
  }

  const allRepos: GitHubRepoRaw[] = []
  let page = 1
  const perPage = 100
  const maxPages = 10 // Cap at 1000 repos

  while (page <= maxPages) {
    const url = accessToken
      ? `${GITHUB_API}/user/repos?sort=updated&per_page=${perPage}&page=${page}&affiliation=owner,collaborator,organization_member`
      : `${GITHUB_API}/users/${username}/repos?sort=updated&per_page=${perPage}&page=${page}`

    const response = await fetch(url, { headers })

    if (!response.ok) {
      // Cancel the response body to avoid stalled connections in Workers
      response.body?.cancel()
      throw new Error(`GitHub API error: ${response.status}`)
    }

    const repos = await response.json<GitHubRepoRaw[]>()
    allRepos.push(...repos)

    if (repos.length < perPage) {
      break
    }
    page++
  }

  return allRepos
}

// Check if a branch exists in a repository
// Returns: true (exists), false (doesn't exist), null (error/unknown/no token)
export async function checkBranchExists(
  repoFullName: string,
  branchName: string,
  accessToken: string | null,
): Promise<boolean | null> {
  // Can't check without a token
  if (!accessToken) {
    return null
  }
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
    Authorization: `Bearer ${accessToken}`,
  }

  const url = `${GITHUB_API}/repos/${repoFullName}/branches/${encodeURIComponent(branchName)}`
  const response = await fetch(url, { headers })

  if (response.ok) {
    // GitHub may redirect branch names (e.g., master -> main for default branch)
    // Verify the returned branch name actually matches what we requested
    const data = (await response.json()) as { name?: string }
    if (data.name !== branchName) {
      console.log(
        `[checkBranchExists] ${repoFullName}/${branchName} -> redirected to ${data.name}, treating as not found`,
      )
      return false
    }
    return true
  }

  // Cancel body for non-OK responses
  response.body?.cancel()

  // 404 = branch doesn't exist (definitive answer)
  if (response.status === 404) {
    return false
  }

  // 403/429/5xx = unknown (rate limit, auth issue, server error)
  console.error(`checkBranchExists error for ${repoFullName}/${branchName}: ${response.status}`)
  return null
}

export interface DeleteBranchResult {
  deleted: boolean
  reason: "deleted" | "missing" | "blocked"
  message?: string
}

export async function deleteBranch(
  repoFullName: string,
  branchName: string,
  accessToken: string,
): Promise<DeleteBranchResult> {
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
    Authorization: `Bearer ${accessToken}`,
  }

  const response = await fetch(
    `${GITHUB_API}/repos/${repoFullName}/git/refs/heads/${encodeURIComponent(branchName)}`,
    {
      method: "DELETE",
      headers,
    },
  )

  if (response.ok) {
    return { deleted: true, reason: "deleted" }
  }

  if (response.status === 404) {
    response.body?.cancel()
    return { deleted: false, reason: "missing" }
  }

  let errorMessage: string | undefined
  try {
    const data = await response.json<{ message?: string }>()
    if (typeof data.message === "string") {
      errorMessage = data.message
    }
  } catch {
    response.body?.cancel()
  }

  if (response.status === 422) {
    return {
      deleted: false,
      reason: "blocked",
      message: errorMessage ?? "GitHub refused to delete the branch",
    }
  }

  throw new Error(
    `Failed to delete branch '${branchName}': ${response.status}${errorMessage ? ` ${errorMessage}` : ""}`,
  )
}

// Compare two branches and return whether head is ahead of base
export interface BranchCompareResult {
  ahead_by: number
  behind_by: number
  status: "ahead" | "behind" | "identical" | "diverged"
}

export async function compareBranchStatus(
  repoFullName: string,
  base: string,
  head: string,
  accessToken: string,
): Promise<BranchCompareResult | null> {
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
    Authorization: `Bearer ${accessToken}`,
  }

  const url = `${GITHUB_API}/repos/${repoFullName}/compare/${encodeURIComponent(base)}...${encodeURIComponent(head)}`
  const response = await fetch(url, { headers })

  if (!response.ok) {
    response.body?.cancel()
    // 404 = one of the branches doesn't exist
    if (response.status === 404) {
      return null
    }
    console.error(
      `compareBranchStatus error for ${repoFullName} ${base}...${head}: ${response.status}`,
    )
    return null
  }

  const data = await response.json<{
    ahead_by: number
    behind_by: number
    status: "ahead" | "behind" | "identical" | "diverged"
  }>()

  return {
    ahead_by: data.ahead_by,
    behind_by: data.behind_by,
    status: data.status,
  }
}

// Full installation data from GitHub API
export interface GitHubInstallation {
  id: number
  account: {
    login: string
    id: number
    type: string // 'User' or 'Organization'
  }
  app_slug?: string
  suspended_at?: string | null
}

// Result type for installation fetch - includes error state
export type InstallationsResult = {
  installations: GitHubInstallation[]
  error: boolean // true if we encountered an error (partial results)
}

// Fetch all GitHub App installations the user has access to
// Returns error: true if we couldn't complete the fetch (for accurate downstream handling)
export async function fetchUserInstallations(accessToken: string): Promise<InstallationsResult> {
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
    Authorization: `Bearer ${accessToken}`,
  }

  const allInstallations: GitHubInstallation[] = []
  let page = 1
  const perPage = 100
  const maxPages = 5 // Cap at 500 installations

  while (page <= maxPages) {
    const url = `${GITHUB_API}/user/installations?per_page=${perPage}&page=${page}`
    const response = await fetch(url, { headers })

    if (!response.ok) {
      // Cancel the response body to avoid stalled connections in Workers
      response.body?.cancel()
      console.error(`Failed to fetch user installations: ${response.status}`)
      return { installations: allInstallations, error: true }
    }

    const data = await response.json<{
      total_count: number
      installations: Array<{
        id: number
        account: { login: string; id: number; type: string }
        app_slug?: string
        suspended_at?: string | null
      }>
    }>()

    // Map to our GitHubInstallation type
    for (const inst of data.installations) {
      allInstallations.push({
        id: inst.id,
        account: {
          login: inst.account.login,
          id: inst.account.id,
          type: inst.account.type,
        },
        app_slug: inst.app_slug,
        suspended_at: inst.suspended_at,
      })
    }

    if (data.installations.length < perPage) {
      break
    }
    page++
  }

  return { installations: allInstallations, error: false }
}

// Repo data returned by fetchInstallationRepos
export interface InstallationRepo {
  github_id: number
  full_name: string
  name: string
  description: string | null
  html_url: string
  language: string | null
  stargazers_count: number
  is_fork: boolean
  is_archived: boolean
  is_private: boolean
  pushed_at: string | null
  default_branch: string
}

// Fetch all repos for a specific installation
// Returns array of repo data, or null on error
export async function fetchInstallationRepos(
  installationId: number,
  accessToken: string,
): Promise<InstallationRepo[] | null> {
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
    Authorization: `Bearer ${accessToken}`,
  }

  const allRepos: InstallationRepo[] = []
  let page = 1
  const perPage = 100
  const maxPages = 20 // Cap at 2000 repos per installation

  while (page <= maxPages) {
    const url = `${GITHUB_API}/user/installations/${installationId}/repositories?per_page=${perPage}&page=${page}`
    const response = await fetch(url, { headers })

    if (!response.ok) {
      response.body?.cancel()
      console.error(
        `fetchInstallationRepos error for installation ${installationId}: ${response.status}`,
      )
      return null // Return null on error to distinguish from empty repos
    }

    const data = await response.json<{
      total_count: number
      repositories: Array<{
        id: number
        full_name: string
        name: string
        description: string | null
        html_url: string
        language: string | null
        stargazers_count: number
        fork: boolean
        archived: boolean
        private: boolean
        pushed_at: string | null
        default_branch: string
      }>
    }>()

    for (const repo of data.repositories) {
      allRepos.push({
        github_id: repo.id,
        full_name: repo.full_name,
        name: repo.name,
        description: repo.description,
        html_url: repo.html_url,
        language: repo.language,
        stargazers_count: repo.stargazers_count,
        is_fork: repo.fork,
        is_archived: repo.archived,
        is_private: repo.private,
        pushed_at: repo.pushed_at,
        default_branch: repo.default_branch,
      })
    }

    if (data.repositories.length < perPage) {
      break
    }
    page++
  }

  return allRepos
}

// Fetch user's contribution data
// Note: GitHub doesn't have a public API for contributions graph
// This uses the public profile page scraping approach or GraphQL
export async function fetchUserContributions(
  username: string,
  accessToken?: string,
): Promise<{
  total_count: number
  contributions: Array<{ date: string; count: number }>
}> {
  // If we have an access token, use GraphQL API
  if (accessToken) {
    const query = `
      query($username: String!) {
        user(login: $username) {
          contributionsCollection {
            contributionCalendar {
              totalContributions
              weeks {
                contributionDays {
                  date
                  contributionCount
                }
              }
            }
          }
        }
      }
    `

    const response = await fetch("https://api.github.com/graphql", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${accessToken}`,
        "User-Agent": "gh-social-api",
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ query, variables: { username } }),
    })

    if (response.ok) {
      const data = await response.json<{
        data: {
          user: {
            contributionsCollection: {
              contributionCalendar: {
                totalContributions: number
                weeks: Array<{
                  contributionDays: Array<{
                    date: string
                    contributionCount: number
                  }>
                }>
              }
            }
          }
        }
      }>()

      const calendar = data.data.user.contributionsCollection.contributionCalendar

      const contributions = calendar.weeks.flatMap((week) =>
        week.contributionDays.map((day) => ({
          date: day.date,
          count: day.contributionCount,
        })),
      )

      return {
        total_count: calendar.totalContributions,
        contributions,
      }
    } else {
      // Cancel the response body to avoid stalled connections in Workers
      response.body?.cancel()
    }
  }

  // Fallback: return empty data
  // In production, you might scrape the public profile or use a different approach
  return {
    total_count: 0,
    contributions: [],
  }
}

