// TTL for ETag entries in KV (7 days)
const ETAG_KV_TTL = 60 * 60 * 24 * 7

function etagCacheKey(repo: string, branch: string | undefined, page: number): string {
  return `etag:commits:${repo}:${branch ?? "default"}:${page}`
}

export interface CommitsPageResult {
  commits: CommitInfo[]
  rateLimitRemaining: number | null
  rateLimitResetAt: number | null
  notModified?: boolean
}

export async function fetchRepoCommitsPageWithMeta(
  repoFullName: string,
  branch?: string,
  accessToken?: string,
  page: number = 1,
  limit: number = 30,
  since?: string,
  until?: string,
  cache?: KVNamespace,
): Promise<CommitsPageResult> {
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
  }

  if (accessToken) {
    headers.Authorization = `Bearer ${accessToken}`
  }

  // ETag conditional request: look up cached ETag from KV
  // Wrapped in try-catch so KV errors don't kill the entire sync
  const cacheKey = cache ? etagCacheKey(repoFullName, branch, page) : null
  if (cache && cacheKey) {
    try {
      const cachedEtag = await cache.get(cacheKey)
      if (cachedEtag) {
        headers["If-None-Match"] = cachedEtag
      }
    } catch {
      // KV lookup failed — proceed without ETag (normal fetch)
    }
  }

  let url = `${GITHUB_API}/repos/${repoFullName}/commits?per_page=${limit}&page=${page}`
  if (branch) {
    url += `&sha=${encodeURIComponent(branch)}`
  }
  if (since) {
    url += `&since=${encodeURIComponent(since)}`
  }
  if (until) {
    url += `&until=${encodeURIComponent(until)}`
  }

  const response = await fetch(url, { headers })

  // 304 Not Modified — nothing changed since last fetch
  if (response.status === 304) {
    response.body?.cancel()
    return {
      commits: [],
      rateLimitRemaining: response.headers.get("X-RateLimit-Remaining")
        ? parseInt(response.headers.get("X-RateLimit-Remaining")!, 10)
        : null,
      rateLimitResetAt: response.headers.get("X-RateLimit-Reset")
        ? parseInt(response.headers.get("X-RateLimit-Reset")!, 10)
        : null,
      notModified: true,
    }
  }

  if (!response.ok) {
    const rateLimit = isRateLimited(response)
    if (rateLimit.limited) {
      response.body?.cancel()
      throw new GitHubRateLimitError(
        `Failed to fetch commits: ${response.status}`,
        response.status,
        rateLimit.resetAt,
      )
    }
    // Cancel the response body to avoid stalled connections in Workers
    response.body?.cancel()
    throw new Error(`Failed to fetch commits: ${response.status}`)
  }

  // Store new ETag in KV for future conditional requests
  const newEtag = response.headers.get("ETag")
  if (cache && cacheKey && newEtag) {
    // Fire-and-forget — don't block on KV write
    cache.put(cacheKey, newEtag, { expirationTtl: ETAG_KV_TTL }).catch(() => {})
  }

  const commits = await response.json<
    Array<{
      sha: string
      commit: {
        message: string
        author: {
          name: string
          date: string
        }
      }
      author: {
        login: string
        id: number
      } | null
      html_url: string
    }>
  >()

  return {
    commits: commits.map((c) => ({
      sha: c.sha,
      message: c.commit.message,
      author: c.commit.author.name,
      authorUsername: c.author?.login ?? null,
      authorId: c.author?.id ?? null,
      date: c.commit.author.date,
      url: c.html_url,
    })),
    rateLimitRemaining: response.headers.get("X-RateLimit-Remaining")
      ? parseInt(response.headers.get("X-RateLimit-Remaining")!, 10)
      : null,
    rateLimitResetAt: response.headers.get("X-RateLimit-Reset")
      ? parseInt(response.headers.get("X-RateLimit-Reset")!, 10)
      : null,
  }
}

