export async function getCommitsForBranch(
  db: Kysely<DB>,
  repoId: string,
  branch: string,
  options: { limit?: number } = {},
): Promise<CommitListItem[]> {
  const { limit = 100 } = options

  const commitRows = await db
    .selectFrom("repo_branch_commits as bc")
    .innerJoin("repo_commits as rc", (join) =>
      join.onRef("rc.repo_id", "=", "bc.repo_id").onRef("rc.commit_sha", "=", "bc.commit_sha"),
    )
    .select([
      "bc.commit_sha",
      "rc.commit_message",
      "rc.commit_author_username",
      "rc.commit_date",
      "rc.additions",
      "rc.deletions",
      "rc.files_changed",
    ])
    .where("bc.repo_id", "=", repoId)
    .where("bc.branch", "=", branch)
    .orderBy("rc.commit_date", "desc")
    .limit(limit)
    .execute()

  if (commitRows.length === 0) return []

  const commitShas = commitRows.map((row) => row.commit_sha)
  const checkpointRows = await db
    .selectFrom("repo_checkpoint_commits as cc")
    .leftJoin("repo_checkpoints as cp", (join) =>
      join
        .onRef("cp.repo_id", "=", "cc.repo_id")
        .onRef("cp.checkpoint_id", "=", "cc.checkpoint_id"),
    )
    .select([
      "cc.commit_sha",
      "cc.checkpoint_id",
      "cp.prompt",
      "cp.agent",
      "cp.session_count",
      "cp.sessions",
    ])
    .where("cc.repo_id", "=", repoId)
    .where("cc.commit_sha", "in", commitShas)
    .execute()

  const checkpointsBySha = new Map<string, Map<string, CheckpointListItem>>()
  for (const row of checkpointRows) {
    if (!row.commit_sha) continue
    // Parse sessions JSON to extract agents and total steps
    let agents: string[] = []
    let totalSteps = 1
    let firstPrompt: string | null = row.prompt ?? null
    if (row.sessions) {
      try {
        const parsed = (
          typeof row.sessions === "string" ? JSON.parse(row.sessions) : row.sessions
        ) as { prompt?: string; agent: string; steps?: number }[]
        if (Array.isArray(parsed) && parsed.length > 0) {
          agents = [...new Set(parsed.map((s) => s.agent))]
          totalSteps = parsed.reduce((sum, s) => sum + (s.steps ?? 1), 0)
          firstPrompt = parsed[0]?.prompt ?? firstPrompt
        }
