        const stored = await db.checkpoints.updateTranscriptBatch(repoId, dbUpdates)
        log("transcripts_stored", { batchId, repoId, stored, attempted: dbUpdates.length })
      }
    } catch (err) {
      log("transcript_fetch_error", {
        batchId,
        repoId,
        error: err instanceof Error ? err.message : String(err),
      })
      // Continue without transcripts — prompt/commit/files still get indexed
    }
  }

  return transcripts
}

// Process a batch of search index messages
export async function processSearchIndexBatch(
  batch: MessageBatch<SearchIndexMessage>,
  env: Env,
): Promise<void> {
  const batchStartTime = Date.now()
  const batchId = generateBatchId()
  const posthog = createPostHogClient(env)

  const queueWaitTimes = batch.messages.map((msg) => Date.now() - msg.timestamp.getTime())
  const maxWaitMs = queueWaitTimes.length > 0 ? Math.max(...queueWaitTimes) : 0

  log("batch_started", {
    batchId,
    queue: batch.queue,
    count: batch.messages.length,
    avgQueueWaitMs: avgMs(queueWaitTimes),
    maxQueueWaitMs: maxWaitMs,
  })

  const processingTimes: number[] = []
  let successCount = 0
  let errorCount = 0
  let skippedCount = 0

  for (const msg of batch.messages) {
    const msgStartTime = Date.now()
    const { repoId, checkpointIds } = msg.body

    // Early return if API keys are missing — don't retry messages that can never succeed
    if (!env.TURBOPUFFER_API_KEY || !env.OPENAI_API_KEY) {
      log("skip_missing_api_keys", {
        batchId,
        repoId,
        hasTurbopuffer: !!env.TURBOPUFFER_API_KEY,
        hasOpenai: !!env.OPENAI_API_KEY,
      })
      msg.ack()
      skippedCount++
      continue
    }

    try {
      const db = getDb(env)

      const repo = await db.repos.getById(repoId)
      if (!repo) {
        log("skip_repo_not_found", { batchId, repoId })
        msg.ack()
        skippedCount++
        continue
      }

      // Feature flag gate: only index repos whose org has the flag explicitly enabled.
      // If PostHog is unavailable (undefined), we skip rather than risk indexing wrong orgs.
      const repoOrg = repo.full_name.split("/")[0]?.toLowerCase()
      const flagResult = await isFeatureEnabled(
        posthog,
        "semantic-search-api",
        repoOrg ?? "",
        repo.full_name.toLowerCase(),
      )

      if (flagResult !== true) {
        log("skip_flag_not_enabled", {
          batchId,
          repoId,
          org: repoOrg,
          flag: "semantic-search-api",
          flagResult: flagResult ?? "undefined",
        })
        msg.ack()
        skippedCount++
        continue
      }

      const checkpoints = await db.checkpoints.getByIds(repoId, checkpointIds)

      if (checkpoints.length === 0) {
        log("skip_no_checkpoints", { batchId, repoId, requestedIds: checkpointIds.length })
        msg.ack()
        skippedCount++
        continue
      }

      const checkpointRepoName = getCheckpointRepoName(repo)

      const transcripts = await ensureTranscriptsStored(
        db,
        repoId,
        checkpointRepoName,
        repo.installation_id,
        checkpoints.map((cp) => ({
          checkpoint_id: cp.checkpoint_id,
          agent: cp.agent ?? "Claude Code",
          session_count: cp.session_count ?? 1,
        })),
        env,
        batchId,
      )

      // Build chunks for each checkpoint from its transcript (session 0),
      // falling back to a single metadata chunk when no transcript is available.
      const checkpointWithChunks = checkpoints.map((cp) => {
        const jsonl = transcripts.get(cp.checkpoint_id) ?? null
        let chunks: SearchChunk[] = []

        if (jsonl) {
          try {
            const parser = getParserForAgent(cp.agent ?? "Claude Code")
            const { messages } = parser.parse(jsonl)
            chunks = chunkTranscript(messages, cp.checkpoint_id)
          } catch {
            // fall through to metadata-only fallback below
          }
        }

        if (chunks.length === 0) {
          // Fallback: single chunk from prompt + commit + files (no transcript)
          const text = buildSearchText({
            prompt: cp.prompt,
            commit_message: cp.commit_message,
            files_touched: cp.files_touched,
          })
          if (text.trim()) {
            chunks = [
              {
                chunkId: makeChunkId(cp.checkpoint_id, 0),
                checkpointId: cp.checkpoint_id,
                chunkIndex: 0,
                text,
                turnStart: 0,
                turnEnd: 0,
                tokenEstimate: Math.ceil(text.length / 4),
                chunkVersion: CHUNK_VERSION,
              },
            ]
          }
        }

        return {
          checkpoint_id: cp.checkpoint_id,
          branch: cp.branch,
          agent: cp.agent,
          commit_author_username: cp.commit_author_username,
          created_at: cp.created_at,
          commit_sha: cp.commit_sha,
          commit_message: cp.commit_message,
          prompt: cp.prompt,
          files_touched: cp.files_touched,
          chunks,
        }
      })

      // Pass org info so chunks are dual-written to the org-level namespace.
      // Org name is derived from full_name (e.g., "acme/backend-api" → "acme").
      const orgName = repo.full_name.split("/")[0]
      const orgInfo: OrgInfo | undefined = orgName
        ? { orgName, repoGithubId: repo.github_id }
        : undefined

      const indexed = await indexCheckpointChunks(
        env.TURBOPUFFER_API_KEY,
        env.OPENAI_API_KEY,
        repo.github_id,
        checkpointWithChunks,
        orgInfo,
      )

      const processingMs = Date.now() - msgStartTime
      processingTimes.push(processingMs)

      log("message_processed", {
        batchId,
        repoId,
        requested: checkpointIds.length,
        found: checkpoints.length,
        indexed,
        processingMs,
        attempt: msg.attempts,
      })

      msg.ack()
      successCount++
    } catch (err) {
      const processingMs = Date.now() - msgStartTime
      processingTimes.push(processingMs)
      errorCount++

      log("message_error", {
        batchId,
        repoId,
        checkpointCount: checkpointIds.length,
        attempt: msg.attempts,
        processingMs,
        error: err instanceof Error ? err.message : String(err),
      })

      // Retry on transient failures (max_retries configured in wrangler.jsonc)
      msg.retry()
    }
  }

  // Shutdown PostHog client to stop polling timers
  await shutdownPostHogClient(posthog)

  const totalBatchTimeMs = Date.now() - batchStartTime

  log("batch_complete", {
    batchId,
    count: batch.messages.length,
    successCount,
    errorCount,
    skippedCount,
    totalBatchTimeMs,
    avgProcessingMs: avgMs(processingTimes),
    throughputPerMin:
      totalBatchTimeMs > 0 ? Math.round((batch.messages.length / totalBatchTimeMs) * 60000) : 0,
  })
}

