import { describe, it, expect } from "vitest"

import { parseSessionsFromRow, mapCheckpointToInfo } from "./checkpoint-mapper"
import type { CheckpointWithCommit } from "./db/checkpoints"

function makeRow(overrides: Partial<CheckpointWithCommit> = {}): CheckpointWithCommit {
  return {
    checkpoint_id: "aee5e709f5d2",
    branch: "main",
    prompt: "fix the bug",
    agent: "Claude Code",
    steps: 3,
    session_count: 1,
    strategy: "manual-commit",
    created_at: "2026-03-10T14:00:00Z",
    commit_sha: "abc123",
    commit_message: "fix: the bug",
    commit_author: "test",
    commit_author_username: "test",
    commit_date: "2026-03-10T14:00:00Z",
    additions: 10,
    deletions: 2,
    files_changed: 3,
    files_touched: ["src/foo.ts"],
    file_stats: null,
    input_tokens: null,
    cache_creation_tokens: null,
    cache_read_tokens: null,
    output_tokens: null,
    api_call_count: null,
    attribution_agent_lines: null,
    attribution_human_added: null,
    attribution_human_modified: null,
    attribution_human_removed: null,
    attribution_total_committed: null,
    attribution_agent_percentage: null,
    attribution_calculated_at: null,
    sessions: null,
    ...overrides,
  }
}

describe("parseSessionsFromRow", () => {
  it("falls back to single session from agent field when sessions is null", () => {
    const row = makeRow({ sessions: null, agent: "Cursor", prompt: "do stuff", steps: 2 })
    const result = parseSessionsFromRow(row)

    expect(result).toEqual([{ prompt: "do stuff", agent: "Cursor", steps: 2 }])
  })

  it("defaults agent to Claude Code when agent field is missing", () => {
    const row = makeRow({ sessions: null, agent: undefined as unknown as string })
    const result = parseSessionsFromRow(row)

    expect(result[0].agent).toBe("Claude Code")
  })

  it("parses sessions JSON array when present", () => {
    const sessions = [
      { prompt: "first", agent: "Claude Code", steps: 2 },
      { prompt: null, agent: "Mock Lifecycle Agent", steps: 1 },
    ]
    const row = makeRow({ sessions: JSON.stringify(sessions) })
    const result = parseSessionsFromRow(row)

    expect(result).toHaveLength(2)
    expect(result[0].agent).toBe("Claude Code")
    expect(result[1].agent).toBe("Mock Lifecycle Agent")
  })

  it("handles sessions as already-parsed object (not string)", () => {
    const sessions = [
      { prompt: "p1", agent: "Cursor", steps: 1 },
      { prompt: "p2", agent: "Claude Code", steps: 3 },
    ]
    const row = makeRow({ sessions: sessions as unknown as CheckpointWithCommit["sessions"] })
    const result = parseSessionsFromRow(row)

    expect(result).toHaveLength(2)
    expect(result[0].agent).toBe("Cursor")
    expect(result[1].agent).toBe("Claude Code")
  })

  it("falls back when sessions JSON is invalid", () => {
    const row = makeRow({
      sessions: "not valid json" as unknown as CheckpointWithCommit["sessions"],
      agent: "Gemini",
    })
    const result = parseSessionsFromRow(row)

    expect(result).toEqual([{ prompt: row.prompt, agent: "Gemini", steps: 3 }])
  })

  it("falls back when sessions JSON is an empty array", () => {
    const row = makeRow({
      sessions: "[]" as unknown as CheckpointWithCommit["sessions"],
      agent: "Amp",
    })
    const result = parseSessionsFromRow(row)

    expect(result).toEqual([{ prompt: row.prompt, agent: "Amp", steps: 3 }])
  })
})

describe("mapCheckpointToInfo", () => {
  it("returns single agent when no sessions JSON", () => {
    const row = makeRow({ agent: "Cursor" })
    const info = mapCheckpointToInfo(row)

    expect(info.agents).toEqual(["Cursor"])
    expect(info.sessions).toHaveLength(1)
    expect(info.sessions[0].agent).toBe("Cursor")
  })

  it("returns multiple unique agents from sessions JSON", () => {
    const sessions = [
      { prompt: "p1", agent: "Claude Code", steps: 2 },
      { prompt: null, agent: "Mock Lifecycle Agent", steps: 1 },
    ]
    const row = makeRow({ sessions: JSON.stringify(sessions), session_count: 2 })
    const info = mapCheckpointToInfo(row)

    expect(info.agents).toEqual(["Claude Code", "Mock Lifecycle Agent"])
    expect(info.sessions).toHaveLength(2)
    expect(info.sessionCount).toBe(2)
  })

  it("deduplicates agents when multiple sessions use the same agent", () => {
    const sessions = [
      { prompt: "p1", agent: "Claude Code", steps: 2 },
      { prompt: "p2", agent: "Claude Code", steps: 3 },
    ]
    const row = makeRow({ sessions: JSON.stringify(sessions), session_count: 2 })
    const info = mapCheckpointToInfo(row)

    expect(info.agents).toEqual(["Claude Code"])
    expect(info.sessions).toHaveLength(2)
  })

  it("computes totalSteps from sessions", () => {
    const sessions = [
      { prompt: "p1", agent: "Claude Code", steps: 5 },
      { prompt: "p2", agent: "Cursor", steps: 3 },
    ]
    const row = makeRow({ sessions: JSON.stringify(sessions), session_count: 2 })
    const info = mapCheckpointToInfo(row)

    expect(info.totalSteps).toBe(8)
  })

  it("maps attribution when present", () => {
    const row = makeRow({
      attribution_calculated_at: "2026-03-10T14:00:00Z",
      attribution_agent_lines: 50,
      attribution_human_added: 10,
      attribution_human_modified: 5,
      attribution_human_removed: 2,
      attribution_total_committed: 67,
      attribution_agent_percentage: 75,
    })
    const info = mapCheckpointToInfo(row)

    expect(info.attribution).toEqual({
      calculatedAt: "2026-03-10T14:00:00Z",
      agentLines: 50,
      humanAdded: 10,
      humanModified: 5,
      humanRemoved: 2,
      totalCommitted: 67,
      agentPercentage: 75,
    })
  })

  it("returns null attribution when not calculated", () => {
    const row = makeRow({ attribution_calculated_at: null })
    const info = mapCheckpointToInfo(row)

    expect(info.attribution).toBeNull()
  })

  it("defaults checkpointRepoFullName to null when not provided", () => {
    const info = mapCheckpointToInfo(makeRow())

    expect(info.checkpointRepoFullName).toBeNull()
  })

  it("passes through checkpointRepoFullName when provided", () => {
    const info = mapCheckpointToInfo(makeRow(), "myorg/checkpoints-repo")

    expect(info.checkpointRepoFullName).toBe("myorg/checkpoints-repo")
  })
})

