// Fetch open PRs for a single repo
const MAX_PRS = 10_000
const PRS_PER_PAGE = 100

export async function fetchRepoPRs(
  repoFullName: string,
  headers: Record<string, string>,
  state: "open" | "closed" | "all" = "open",
): Promise<CachedPRs["prs"]> {
  const allPRs: CachedPRs["prs"] = []
  let page = 1

  while (allPRs.length < MAX_PRS) {
    const response = await fetch(
      `${GITHUB_API}/repos/${repoFullName}/pulls?state=${state}&per_page=${PRS_PER_PAGE}&page=${page}`,
      { headers },
    )

    // Repo might be deleted, private, or inaccessible - just return what we have
    if (!response.ok) {
      response.body?.cancel()
      break
    }

    const data = await response.json<
      Array<{
        id: number
        number: number
        title: string
        html_url: string
        state: string
        created_at: string
        updated_at: string
        draft: boolean
        merged_at: string | null
      }>
    >()

    for (const pr of data) {
      allPRs.push({
        id: pr.id,
        number: pr.number,
        title: pr.title,
        html_url: pr.html_url,
        state: pr.state,
        repo_full_name: repoFullName,
        created_at: pr.created_at,
        updated_at: pr.updated_at,
        draft: pr.draft || false,
        merged_at: pr.merged_at || null,
      })
    }

    if (data.length < PRS_PER_PAGE) {
      break
    }
    page++
  }

  return allPRs
}

