describe("isValidBranchName", () => {
  it("accepts valid branch names", () => {
    // Simple names
    expect(isValidBranchName("main")).toBe(true)
    expect(isValidBranchName("master")).toBe(true)
    expect(isValidBranchName("develop")).toBe(true)

    // With hyphens
    expect(isValidBranchName("feature-branch")).toBe(true)
    expect(isValidBranchName("fix-123")).toBe(true)

    // With underscores
    expect(isValidBranchName("feature_branch")).toBe(true)
    expect(isValidBranchName("my_feature_123")).toBe(true)

    // With dots
    expect(isValidBranchName("release-1.0")).toBe(true)
    expect(isValidBranchName("v2.3.4")).toBe(true)

    // With slashes (common for feature branches)
    expect(isValidBranchName("feature/add-auth")).toBe(true)
    expect(isValidBranchName("user/john/experiment")).toBe(true)
    expect(isValidBranchName("refs/heads/main")).toBe(true)

    // Mixed characters
    expect(isValidBranchName("paul/ent-190-missing-branch-parameter-validation")).toBe(true)
    expect(isValidBranchName("feature/ENT-123_add-tests")).toBe(true)
  })

  it("rejects empty branch names", () => {
    expect(isValidBranchName("")).toBe(false)
  })

  it("rejects branch names with spaces", () => {
    expect(isValidBranchName("my branch")).toBe(false)
    expect(isValidBranchName(" main")).toBe(false)
    expect(isValidBranchName("main ")).toBe(false)
  })

  it("rejects branch names with special characters", () => {
    // Characters that could cause issues with cache keys or shell injection
    expect(isValidBranchName("branch;rm -rf")).toBe(false)
    expect(isValidBranchName("branch&echo")).toBe(false)
    expect(isValidBranchName("branch|cat")).toBe(false)
    expect(isValidBranchName("branch`whoami`")).toBe(false)
    expect(isValidBranchName("branch$(id)")).toBe(false)
    expect(isValidBranchName("branch\nmalicious")).toBe(false)
    expect(isValidBranchName("branch\rmalicious")).toBe(false)
    expect(isValidBranchName("branch\tmalicious")).toBe(false)
  })

  it("allows unusual but technically valid branch names", () => {
    // Git allows these names even if they look suspicious
    // The validation focuses on character safety, not semantic meaning
    // Path traversal protection happens at file system level, not branch validation
    expect(isValidBranchName("..")).toBe(true)
    expect(isValidBranchName("../../../etc/passwd")).toBe(true)
  })

  it("rejects branch names with quotes", () => {
    expect(isValidBranchName('branch"test')).toBe(false)
    expect(isValidBranchName("branch'test")).toBe(false)
  })

  it("rejects branch names with brackets and special chars", () => {
    expect(isValidBranchName("branch[0]")).toBe(false)
    expect(isValidBranchName("branch{test}")).toBe(false)
    expect(isValidBranchName("branch<script>")).toBe(false)
    expect(isValidBranchName("branch@test")).toBe(false)
    expect(isValidBranchName("branch#test")).toBe(false)
    expect(isValidBranchName("branch%test")).toBe(false)
    expect(isValidBranchName("branch*")).toBe(false)
    expect(isValidBranchName("branch?")).toBe(false)
    expect(isValidBranchName("branch!")).toBe(false)
    expect(isValidBranchName("branch~")).toBe(false)
    expect(isValidBranchName("branch^")).toBe(false)
    expect(isValidBranchName("branch:test")).toBe(false)
  })

  it("rejects branch names exceeding max length", () => {
    // 256 characters should be the limit
    const longValidName = "a".repeat(256)
    expect(isValidBranchName(longValidName)).toBe(true)

    const tooLongName = "a".repeat(257)
    expect(isValidBranchName(tooLongName)).toBe(false)
  })

  it("rejects unicode characters", () => {
    expect(isValidBranchName("branch-émoji")).toBe(false)
    expect(isValidBranchName("branch-日本語")).toBe(false)
    expect(isValidBranchName("branch-🚀")).toBe(false)
  })
})

