describe("applyPatchLimits", () => {
  it("passes through small patches unchanged", () => {
    const result = applyPatchLimits([
      { filename: "a.ts", status: "modified", additions: 1, deletions: 1, patch: "small diff" },
    ])

    expect(result).toHaveLength(1)
    expect(result[0].patch).toBe("small diff")
    expect(result[0].patchTruncated).toBeUndefined()
    expect(result[0].filename).toBe("a.ts")
    expect(result[0].status).toBe("modified")
  })

  it("truncates patch exceeding 50KB per-file limit", () => {
    const largePatch = "x".repeat(60 * 1024)
    const result = applyPatchLimits([
      { filename: "big.ts", status: "modified", additions: 1, deletions: 0, patch: largePatch },
    ])

    expect(result[0].patchTruncated).toBe(true)
    expect(result[0].patch).not.toBeNull()
    expect(result[0].patch!.endsWith("\n... [truncated]")).toBe(true)
    expect(result[0].patch!.length).toBeLessThan(largePatch.length)
  })

  it("nulls patch when cumulative total exceeds 500KB", () => {
    // 11 files with 49KB patches each: total = 539KB > 500KB
    const files = Array.from({ length: 11 }, (_, i) => ({
      filename: `file${i}.ts`,
      status: "modified",
      additions: 1,
      deletions: 0,
      patch: "x".repeat(49 * 1024),
    }))

    const result = applyPatchLimits(files)

    const nulled = result.filter((f) => f.patch === null)
    expect(nulled.length).toBeGreaterThan(0)
    nulled.forEach((f) => {
      expect(f.patchTruncated).toBe(true)
    })
  })

  it("passes through files without patches", () => {
    const result = applyPatchLimits([
      { filename: "binary.png", status: "added", additions: 0, deletions: 0 },
    ])

    expect(result[0].patch).toBeNull()
    expect(result[0].patchTruncated).toBeUndefined()
  })

  it("maps status string to FileStats status", () => {
    const statuses = ["added", "removed", "modified", "renamed", "copied", "changed"] as const
    const files = statuses.map((s) => ({
      filename: `${s}.ts`,
      status: s,
      additions: 0,
      deletions: 0,
    }))

    const result = applyPatchLimits(files)
    statuses.forEach((s, i) => {
      expect(result[i].status).toBe(s)
    })
  })

  it("nulls oversized file when total budget is exhausted", () => {
    // Fill up most of the 500KB budget with many small files
    const fillers = Array.from({ length: 10 }, (_, i) => ({
      filename: `f${i}.ts`,
      status: "modified",
      additions: 1,
      deletions: 0,
      patch: "x".repeat(49 * 1024), // 49KB each, 490KB total
    }))
    // 11th file is oversized: totalPatchSize(490KB) + 50KB = 540KB > 500KB => null
    const big = {
      filename: "big.ts",
      status: "modified",
      additions: 1,
      deletions: 0,
      patch: "y".repeat(60 * 1024),
    }

    const result = applyPatchLimits([...fillers, big])

    expect(result[10].patch).toBeNull()
    expect(result[10].patchTruncated).toBe(true)
  })
})

