} from "./github"

describe("parseTrailers", () => {
  it("parses a single trailer", () => {
    const message = `Add new feature

This commit adds a new feature.

Entire-Checkpoint: abc123`

    expect(parseTrailers(message)).toEqual({
      "Entire-Checkpoint": ["abc123"],
    })
  })

  it("parses multiple trailers with different keys", () => {
    const message = `Fix bug in auth

Entire-Checkpoint: def456
Co-authored-by: Alice <alice@example.com>
Signed-off-by: Bob <bob@example.com>`

    expect(parseTrailers(message)).toEqual({
      "Entire-Checkpoint": ["def456"],
      "Co-authored-by": ["Alice <alice@example.com>"],
      "Signed-off-by": ["Bob <bob@example.com>"],
    })
  })

  it("parses multiple trailers with the same key (squashed commits)", () => {
    const message = `Squashed commit from feature branch

This PR implements multiple features.

Entire-Checkpoint: abc123
Entire-Checkpoint: def456
Entire-Checkpoint: ghi789
Co-authored-by: Alice <alice@example.com>`

    expect(parseTrailers(message)).toEqual({
      "Entire-Checkpoint": ["abc123", "def456", "ghi789"],
      "Co-authored-by": ["Alice <alice@example.com>"],
    })
  })

  it("returns empty object for message with no trailers", () => {
    const message = `Simple commit message

This is just a body with no trailers.
Just plain text.`

    expect(parseTrailers(message)).toEqual({})
  })

  it("ignores lines that don't match trailer format", () => {
    const message = `Update docs

Some notes:
- Item one
- Item two

Entire-Checkpoint: xyz789`

    expect(parseTrailers(message)).toEqual({
      "Entire-Checkpoint": ["xyz789"],
    })
  })

  it("handles message with only subject line", () => {
    const message = "Just a subject"
    expect(parseTrailers(message)).toEqual({})
  })

  it("handles trailers with hyphenated keys", () => {
    const message = `Commit

Some-Custom-Trailer: value123
Another-One: value456`

    expect(parseTrailers(message)).toEqual({
      "Some-Custom-Trailer": ["value123"],
      "Another-One": ["value456"],
    })
  })

  it("handles trailers with spaces in values", () => {
    const message = `Commit

Co-authored-by: Alice Smith <alice@example.com>`

    expect(parseTrailers(message)).toEqual({
      "Co-authored-by": ["Alice Smith <alice@example.com>"],
    })
  })

  it("stops parsing when hitting non-trailer line after trailers", () => {
    const message = `Commit

This is body text.

Entire-Checkpoint: abc123`

    expect(parseTrailers(message)).toEqual({
      "Entire-Checkpoint": ["abc123"],
    })
  })

  it("handles empty message", () => {
    expect(parseTrailers("")).toEqual({})
  })
})

describe("extractCheckpointIds", () => {
  it("extracts checkpoint ID from standard trailer at end", () => {
    const message = `Add feature

Entire-Checkpoint: abc123`

    expect(extractCheckpointIds(message)).toEqual(["abc123"])
  })

  it("extracts multiple checkpoint IDs from trailer block", () => {
    const message = `Squashed commit

Entire-Checkpoint: abc123
Entire-Checkpoint: def456
Entire-Checkpoint: ghi789`

    expect(extractCheckpointIds(message)).toEqual(["abc123", "def456", "ghi789"])
  })

  it("extracts checkpoint IDs from GitHub squash-merge format (inline with bullets)", () => {
    const message = `Soph/test branch (#2)

* random_letter script

Entire-Checkpoint: 0aa0814d9839

* random color

Entire-Checkpoint: 33fb587b6fbb`

    expect(extractCheckpointIds(message)).toEqual(["0aa0814d9839", "33fb587b6fbb"])
  })

  it("extracts checkpoint IDs scattered throughout message", () => {
    const message = `Feature branch squash

* First commit
Some description
Entire-Checkpoint: first123

* Second commit
More work here
Entire-Checkpoint: second456

* Third commit
Final touches
Entire-Checkpoint: third789`

    expect(extractCheckpointIds(message)).toEqual(["first123", "second456", "third789"])
  })

  it("returns empty array for message with no checkpoint IDs", () => {
    const message = `Regular commit

No checkpoints here.
Co-authored-by: Alice`

    expect(extractCheckpointIds(message)).toEqual([])
  })

  it("handles empty message", () => {
    expect(extractCheckpointIds("")).toEqual([])
  })

  it("ignores partial matches", () => {
    const message = `Some text mentioning Entire-Checkpoint in prose
Not a real trailer: Entire-Checkpoint: fake

Entire-Checkpoint: real123`

    // Only matches lines that START with "Entire-Checkpoint:"
    expect(extractCheckpointIds(message)).toEqual(["real123"])
  })
})

describe("parseSquashCommitTitles", () => {
  it("parses GitHub squash-merge format with PR title", () => {
    const message = `Soph/test branch (#2)

* random_letter script

Entire-Checkpoint: 0aa0814d9839

* random color

Entire-Checkpoint: 33fb587b6fbb`

    const result = parseSquashCommitTitles(message)
    expect(result.get("0aa0814d9839")).toBe("Soph/test branch (#2) * random_letter script")
    expect(result.get("33fb587b6fbb")).toBe("Soph/test branch (#2) * random color")
  })

  it("returns empty map for non-squash commit (no PR number)", () => {
    const message = `Regular commit message

Entire-Checkpoint: abc123`

    expect(parseSquashCommitTitles(message).size).toBe(0)
  })

  it("returns empty map for single commit with PR title but no bullet points", () => {
    const message = `Fix bug (#45)

Entire-Checkpoint: abc123`

    expect(parseSquashCommitTitles(message).size).toBe(0)
  })

  it("handles multiple commits with descriptions between them", () => {
    const message = `Feature branch (#123)

* First commit
Some description text here

Entire-Checkpoint: first123

* Second commit
More description

Entire-Checkpoint: second456`

    const result = parseSquashCommitTitles(message)
    expect(result.get("first123")).toBe("Feature branch (#123) * First commit")
    expect(result.get("second456")).toBe("Feature branch (#123) * Second commit")
  })

  it("handles empty message", () => {
    expect(parseSquashCommitTitles("").size).toBe(0)
  })
})

describe("checkBranchExists", () => {
  const originalFetch = globalThis.fetch

  beforeEach(() => {
    vi.restoreAllMocks()
  })

  afterEach(() => {
    globalThis.fetch = originalFetch
  })

  it("returns true when branch exists", async () => {
    globalThis.fetch = vi.fn().mockResolvedValue({
      ok: true,
      json: async () => ({ name: "main" }),
    }) as typeof fetch

    const result = await checkBranchExists("owner/repo", "main", "test-token")

    expect(result).toBe(true)
    expect(globalThis.fetch).toHaveBeenCalledWith(
      "https://api.github.com/repos/owner/repo/branches/main",
      expect.objectContaining({
        headers: expect.objectContaining({
          Authorization: "Bearer test-token",
        }),
      }),
    )
  })

  it("returns false when branch does not exist (404)", async () => {
    globalThis.fetch = vi.fn().mockResolvedValue({
      ok: false,
      status: 404,
      body: { cancel: vi.fn() },
    }) as typeof fetch

    const result = await checkBranchExists("owner/repo", "nonexistent", "test-token")

    expect(result).toBe(false)
  })

  it("returns false when GitHub redirects to different branch name", async () => {
    // GitHub may redirect master -> main for default branch
    globalThis.fetch = vi.fn().mockResolvedValue({
      ok: true,
      json: async () => ({ name: "main" }), // Asked for master, got main
    }) as typeof fetch

    const result = await checkBranchExists("owner/repo", "master", "test-token")

    expect(result).toBe(false)
  })

  it("returns null for rate limiting (403)", async () => {
    globalThis.fetch = vi.fn().mockResolvedValue({
      ok: false,
      status: 403,
      body: { cancel: vi.fn() },
    }) as typeof fetch

    const result = await checkBranchExists("owner/repo", "main", "test-token")

    expect(result).toBe(null)
  })

  it("returns null for rate limiting (429)", async () => {
    globalThis.fetch = vi.fn().mockResolvedValue({
      ok: false,
      status: 429,
      body: { cancel: vi.fn() },
    }) as typeof fetch

    const result = await checkBranchExists("owner/repo", "main", "test-token")

    expect(result).toBe(null)
  })

  it("returns null for server errors (5xx)", async () => {
    globalThis.fetch = vi.fn().mockResolvedValue({
      ok: false,
      status: 500,
      body: { cancel: vi.fn() },
    }) as typeof fetch

    const result = await checkBranchExists("owner/repo", "main", "test-token")

    expect(result).toBe(null)
  })

  it("encodes branch names with special characters", async () => {
    globalThis.fetch = vi.fn().mockResolvedValue({
      ok: true,
      json: async () => ({ name: "feature/test-branch" }),
    }) as typeof fetch

    await checkBranchExists("owner/repo", "feature/test-branch", "test-token")

    expect(globalThis.fetch).toHaveBeenCalledWith(
      "https://api.github.com/repos/owner/repo/branches/feature%2Ftest-branch",
      expect.any(Object),
    )
  })

  it("returns null when token is null (cannot check without auth)", async () => {
    globalThis.fetch = vi.fn()

    const result = await checkBranchExists("owner/repo", "main", null)

    expect(result).toBe(null)
    expect(globalThis.fetch).not.toHaveBeenCalled()
  })
})

describe("deleteBranch", () => {
