describe("aggregateSessionsToSessionData", () => {
  const makeSession = (overrides: Partial<SessionInfo> = {}): SessionInfo => ({
    prompt: "Default prompt",
    agent: "Claude Code",
    steps: 1,
    sessionId: "sess-1",
    createdAt: "2024-06-01T12:00:00Z",
    ...overrides,
  })

  it("returns defaults for empty sessions array", () => {
    const result = aggregateSessionsToSessionData([], null, null)

    expect(result.prompt).toBe(null)
    expect(result.agent).toBe("Claude Code")
    expect(result.steps).toBe(1)
    expect(result.sessionCount).toBe(1)
    expect(result.strategy).toBe(null)
    expect(result.sessions).toBe(null)
  })

  it("single session — maps all fields correctly", () => {
    const session = makeSession({
      prompt: "Fix the bug",
      agent: "Claude Code",
      steps: 3,
      sessionId: "sess-abc",
      createdAt: "2024-06-01T12:00:00Z",
      tokenUsage: {
        inputTokens: 100,
        cacheCreationTokens: 20,
        cacheReadTokens: 30,
        outputTokens: 50,
        apiCallCount: 2,
      },
      attribution: {
        calculatedAt: "2024-06-01T12:01:00Z",
        agentLines: 10,
        humanAdded: 5,
        humanModified: 2,
        humanRemoved: 1,
        totalCommitted: 18,
        agentPercentage: 55.5,
      },
    })

    const rootSummary: CheckpointSummary = {
      checkpoint_id: "cp-123",
      strategy: "agentic",
      checkpoints_count: 1,
      files_touched: ["src/index.ts"],
      sessions: [],
    }

    const result = aggregateSessionsToSessionData([session], rootSummary, "main")

    expect(result.prompt).toBe("Fix the bug")
    expect(result.agent).toBe("Claude Code")
    expect(result.steps).toBe(3)
    expect(result.sessionCount).toBe(1)
    expect(result.strategy).toBe("agentic")
    expect(result.branch).toBe("main")
    expect(result.sessionId).toBe("sess-abc")
    expect(result.filesTouched).toEqual(["src/index.ts"])
    expect(result.inputTokens).toBe(100)
    expect(result.outputTokens).toBe(50)
    expect(result.attributionAgentLines).toBe(10)
    expect(result.sessions).toEqual([session])
  })

  it("multiple sessions — sums token usage across sessions", () => {
    const sessions = [
      makeSession({
        sessionId: "s1",
        tokenUsage: {
          inputTokens: 100,
          cacheCreationTokens: 10,
          cacheReadTokens: 20,
          outputTokens: 50,
          apiCallCount: 2,
        },
      }),
      makeSession({
        sessionId: "s2",
        tokenUsage: {
          inputTokens: 200,
          cacheCreationTokens: 30,
          cacheReadTokens: 40,
          outputTokens: 100,
          apiCallCount: 3,
        },
      }),
    ]

    const result = aggregateSessionsToSessionData(sessions, null, null)

    expect(result.inputTokens).toBe(300)
    expect(result.cacheCreationTokens).toBe(40)
    expect(result.cacheReadTokens).toBe(60)
    expect(result.outputTokens).toBe(150)
    expect(result.apiCallCount).toBe(5)
  })

  it("multiple sessions — uses latest session for agent/prompt/attribution (fallback without combined_attribution)", () => {
    const sessions = [
      makeSession({
        sessionId: "s1",
        prompt: "First prompt",
        agent: "Agent A",
        attribution: {
          calculatedAt: "2024-06-01T12:00:00Z",
          agentLines: 10,
          humanAdded: 1,
          humanModified: 1,
          humanRemoved: 0,
          totalCommitted: 12,
          agentPercentage: 83.3,
        },
      }),
      makeSession({
        sessionId: "s2",
        prompt: "Second prompt",
        agent: "Agent B",
        attribution: {
          calculatedAt: "2024-06-01T13:00:00Z",
          agentLines: 20,
          humanAdded: 2,
          humanModified: 2,
          humanRemoved: 1,
          totalCommitted: 25,
          agentPercentage: 80.0,
        },
      }),
    ]

    const result = aggregateSessionsToSessionData(sessions, null, null)

    // agent/prompt/sessionId come from latest session
    expect(result.prompt).toBe("Second prompt")
    expect(result.agent).toBe("Agent B")
    expect(result.sessionId).toBe("s2")
    // without combined_attribution, falls back to latest session attribution
    expect(result.attributionAgentLines).toBe(20)
    expect(result.attributionAgentPercentage).toBe(80.0)
    expect(result.attributionCalculatedAt).toBe("2024-06-01T13:00:00Z")
  })

  it("attribution: single non-null session attribution is kept as-is", () => {
    const session = makeSession({
      attribution: {
        calculatedAt: "2024-06-01T12:00:00Z",
        agentLines: 15,
        humanAdded: 3,
        humanModified: 1,
        humanRemoved: 0,
        totalCommitted: 19,
        agentPercentage: 78.9,
      },
    })

    const result = aggregateSessionsToSessionData([session], null, null)

    expect(result.attributionAgentLines).toBe(15)
    expect(result.attributionHumanAdded).toBe(3)
    expect(result.attributionTotalCommitted).toBe(19)
    expect(result.attributionAgentPercentage).toBeCloseTo(78.9, 1)
  })

  it("attribution: multiple sessions with identical attribution tuples — kept", () => {
    const sharedAttribution = {
      calculatedAt: "2024-06-01T12:00:00Z",
      agentLines: 10,
      humanAdded: 2,
      humanModified: 0,
      humanRemoved: 0,
      totalCommitted: 12,
      agentPercentage: 83.3,
    }
    const sessions = [
      makeSession({ sessionId: "s1", attribution: sharedAttribution }),
      makeSession({ sessionId: "s2", attribution: sharedAttribution }),
    ]

    const result = aggregateSessionsToSessionData(sessions, null, null)

    expect(result.attributionAgentLines).toBe(10)
    expect(result.attributionTotalCommitted).toBe(12)
  })

  it("attribution: multiple sessions with distinct non-null attribution — falls back to latest session (no combined_attribution)", () => {
    const sessions = [
      makeSession({
        sessionId: "s1",
        attribution: {
          calculatedAt: "2024-06-01T12:00:00Z",
          agentLines: 5,
          humanAdded: 0,
          humanModified: 0,
          humanRemoved: 0,
          totalCommitted: 5,
          agentPercentage: 100,
        },
      }),
      makeSession({
        sessionId: "s2",
        attribution: {
          calculatedAt: "2024-06-01T13:00:00Z",
          agentLines: 0,
          humanAdded: 5,
          humanModified: 0,
          humanRemoved: 0,
          totalCommitted: 5,
          agentPercentage: 0,
        },
      }),
    ]

    const result = aggregateSessionsToSessionData(sessions, null, null)

    // Without combined_attribution (old checkpoint), falls back to latest session
    expect(result.attributionAgentLines).toBe(0)
    expect(result.attributionHumanAdded).toBe(5)
    expect(result.attributionTotalCommitted).toBe(5)
    expect(result.attributionAgentPercentage).toBe(0)
    expect(result.attributionCalculatedAt).toBe("2024-06-01T13:00:00Z")
  })

  it("attribution: all sessions have null attribution — stays null", () => {
    const sessions = [makeSession({ sessionId: "s1" }), makeSession({ sessionId: "s2" })]

    const result = aggregateSessionsToSessionData(sessions, null, null)

    expect(result.attributionAgentLines).toBe(null)
  })

  it("multiple sessions — sums steps across sessions", () => {
    const sessions = [
      makeSession({ steps: 3 }),
      makeSession({ steps: 5 }),
      makeSession({ steps: 2 }),
    ]

    const result = aggregateSessionsToSessionData(sessions, null, null)
    expect(result.steps).toBe(10)
  })

  it("null rootSummary — falls back to null for strategy/filesTouched", () => {
    const result = aggregateSessionsToSessionData([makeSession()], null, "main")

    expect(result.strategy).toBe(null)
    expect(result.filesTouched).toBe(null)
  })

  it("branch parameter flows through", () => {
    const result = aggregateSessionsToSessionData([makeSession()], null, "feature/test")
    expect(result.branch).toBe("feature/test")
  })

  it("multi-session — prefers combined_attribution from rootSummary over latest session attribution", () => {
    const sessions = [
      makeSession({
        sessionId: "s1",
        attribution: {
          calculatedAt: "2024-06-01T12:00:00Z",
          agentLines: 5,
          humanAdded: 10,
          humanModified: 0,
          humanRemoved: 0,
          totalCommitted: 15,
          agentPercentage: 33.3,
        },
      }),
      makeSession({
        sessionId: "s2",
        attribution: {
          calculatedAt: "2024-06-01T13:00:00Z",
          agentLines: 20,
          humanAdded: 0,
          humanModified: 0,
          humanRemoved: 0,
          totalCommitted: 20,
          agentPercentage: 100.0,
        },
      }),
    ]
    const rootSummary: CheckpointSummary = {
      checkpoint_id: "cp-multi",
      strategy: "manual-commit",
      checkpoints_count: 2,
      files_touched: ["a.ts", "b.ts"],
      sessions: [],
      combined_attribution: {
        calculated_at: "2024-06-01T13:01:00Z",
        agent_lines: 15,
        human_added: 10,
        human_modified: 3,
        human_removed: 2,
        total_committed: 30,
        agent_percentage: 60.0,
      },
    }

    const result = aggregateSessionsToSessionData(sessions, rootSummary, "main")

    expect(result.attributionAgentLines).toBe(15)
    expect(result.attributionHumanAdded).toBe(10)
    expect(result.attributionHumanModified).toBe(3)
    expect(result.attributionHumanRemoved).toBe(2)
    expect(result.attributionTotalCommitted).toBe(30)
    expect(result.attributionAgentPercentage).toBe(60.0)
    expect(result.attributionCalculatedAt).toBe("2024-06-01T13:01:00Z")
  })

  it("single session — falls back to session attribution when no combined_attribution", () => {
    const session = makeSession({
      attribution: {
        calculatedAt: "2024-06-01T12:00:00Z",
        agentLines: 8,
        humanAdded: 2,
        humanModified: 0,
        humanRemoved: 0,
        totalCommitted: 10,
        agentPercentage: 80.0,
      },
    })
    const rootSummary: CheckpointSummary = {
      checkpoint_id: "cp-single",
      strategy: "manual-commit",
      checkpoints_count: 1,
      files_touched: [],
      sessions: [],
      // no combined_attribution
    }

    const result = aggregateSessionsToSessionData([session], rootSummary, "main")

    expect(result.attributionAgentLines).toBe(8)
    expect(result.attributionHumanAdded).toBe(2)
    expect(result.attributionAgentPercentage).toBe(80.0)
  })
})

describe("exchangeCodeForToken - retry logic", () => {
  const originalFetch = globalThis.fetch
  const originalSetTimeout = globalThis.setTimeout

  beforeEach(() => {
    vi.restoreAllMocks()
    // Mock setTimeout to execute immediately for faster tests
    vi.useFakeTimers()
  })

  afterEach(() => {
    globalThis.fetch = originalFetch
    vi.useRealTimers()
  })

  const createSuccessResponse = () => ({
    ok: true,
    json: async () => ({
      access_token: "gho_test_token_123",
      token_type: "bearer",
      scope: "repo,user",
    }),
  })

  const createErrorResponse = (status: number) => ({
    ok: false,
    status,
    body: { cancel: vi.fn() },
  })

  it("succeeds on first attempt without retry", async () => {
    const fetchMock = vi.fn().mockResolvedValue(createSuccessResponse())
    globalThis.fetch = fetchMock as typeof fetch

    const result = await exchangeCodeForToken(
      "test-code",
      "client-id",
      "client-secret",
      "http://localhost/callback",
    )

    expect(result.access_token).toBe("gho_test_token_123")
    expect(fetchMock).toHaveBeenCalledTimes(1)
  })

  it("retries once and succeeds after 503 error", async () => {
    const fetchMock = vi
      .fn()
      .mockResolvedValueOnce(createErrorResponse(503))
      .mockResolvedValueOnce(createSuccessResponse())

    globalThis.fetch = fetchMock as typeof fetch

    const promise = exchangeCodeForToken(
      "test-code",
      "client-id",
      "client-secret",
      "http://localhost/callback",
    )

    // Fast-forward through the retry delays
    await vi.runAllTimersAsync()
    const result = await promise

    expect(result.access_token).toBe("gho_test_token_123")
    expect(fetchMock).toHaveBeenCalledTimes(2)
  })

  it("retries multiple times before success (503, 503, success)", async () => {
    const fetchMock = vi
      .fn()
      .mockResolvedValueOnce(createErrorResponse(503))
      .mockResolvedValueOnce(createErrorResponse(503))
      .mockResolvedValueOnce(createSuccessResponse())

    globalThis.fetch = fetchMock as typeof fetch

    const promise = exchangeCodeForToken(
      "test-code",
      "client-id",
      "client-secret",
      "http://localhost/callback",
    )

    await vi.runAllTimersAsync()
    const result = await promise

    expect(result.access_token).toBe("gho_test_token_123")
    expect(fetchMock).toHaveBeenCalledTimes(3)
  })

  it("exhausts all retries and throws error", async () => {
    const fetchMock = vi
      .fn()
      .mockResolvedValueOnce(createErrorResponse(503))
      .mockResolvedValueOnce(createErrorResponse(503))
      .mockResolvedValueOnce(createErrorResponse(503))

    globalThis.fetch = fetchMock as typeof fetch

    // Start the promise and immediately wrap in expect to catch rejection
    const promise = expect(
      exchangeCodeForToken("test-code", "client-id", "client-secret", "http://localhost/callback"),
    ).rejects.toThrow("GitHub token exchange failed: 503")

    await vi.runAllTimersAsync()
    await promise

    expect(fetchMock).toHaveBeenCalledTimes(3)
  })

  it("does not retry non-retryable client errors (4xx)", async () => {
    const fetchMock = vi.fn().mockResolvedValue(createErrorResponse(400))
    globalThis.fetch = fetchMock as typeof fetch

    await expect(
      exchangeCodeForToken("test-code", "client-id", "client-secret", "http://localhost/callback"),
    ).rejects.toThrow("GitHub token exchange failed: 400")

    // Should only try once (no retries for 4xx errors except 429)
    expect(fetchMock).toHaveBeenCalledTimes(1)
  })

  it("retries 429 Rate Limited errors", async () => {
    const fetchMock = vi
      .fn()
      .mockResolvedValueOnce(createErrorResponse(429))
      .mockResolvedValueOnce(createSuccessResponse())

    globalThis.fetch = fetchMock as typeof fetch

    const promise = exchangeCodeForToken(
      "test-code",
      "client-id",
      "client-secret",
      "http://localhost/callback",
    )

    await vi.runAllTimersAsync()
    const result = await promise

    expect(result.access_token).toBe("gho_test_token_123")
    expect(fetchMock).toHaveBeenCalledTimes(2)
  })

  it("uses exponential backoff with correct delays", async () => {
    const delays: number[] = []
    const originalSetTimeout = global.setTimeout

    // Spy on setTimeout to capture delay values
    vi.spyOn(global, "setTimeout").mockImplementation(((callback: any, ms: number) => {
      delays.push(ms)
      // Actually invoke the callback to progress the test
      callback()
      return 0 as any
    }) as typeof setTimeout)

    const fetchMock = vi
      .fn()
      .mockResolvedValueOnce(createErrorResponse(503))
      .mockResolvedValueOnce(createErrorResponse(503))
      .mockResolvedValueOnce(createSuccessResponse())

    globalThis.fetch = fetchMock as typeof fetch

    await exchangeCodeForToken(
      "test-code",
      "client-id",
      "client-secret",
      "http://localhost/callback",
    )

    // Should have delays of 1000ms, 2000ms for first two retries
    expect(delays).toEqual([1000, 2000])
    expect(fetchMock).toHaveBeenCalledTimes(3)

    global.setTimeout = originalSetTimeout
  })

  it("retries network errors and succeeds", async () => {
    const fetchMock = vi
      .fn()
      .mockRejectedValueOnce(new Error("Network error"))
      .mockResolvedValueOnce(createSuccessResponse())

    globalThis.fetch = fetchMock as typeof fetch

    const promise = exchangeCodeForToken(
      "test-code",
      "client-id",
      "client-secret",
      "http://localhost/callback",
    )

    await vi.runAllTimersAsync()
    const result = await promise

    expect(result.access_token).toBe("gho_test_token_123")
    expect(fetchMock).toHaveBeenCalledTimes(2)
  })

  it("exhausts retries on network errors", async () => {
    const fetchMock = vi.fn().mockRejectedValue(new Error("Network error"))

    globalThis.fetch = fetchMock as typeof fetch

    const promise = expect(
      exchangeCodeForToken("test-code", "client-id", "client-secret", "http://localhost/callback"),
    ).rejects.toThrow("Network error")

    await vi.runAllTimersAsync()
    await promise

    expect(fetchMock).toHaveBeenCalledTimes(3)
  })

  it("handles OAuth error in response body", async () => {
    const fetchMock = vi.fn().mockResolvedValue({
      ok: true,
      json: async () => ({
        error: "invalid_grant",
      }),
    })

    globalThis.fetch = fetchMock as typeof fetch

    await expect(
      exchangeCodeForToken("test-code", "client-id", "client-secret", "http://localhost/callback"),
    ).rejects.toThrow("GitHub OAuth error: invalid_grant")

    // OAuth errors are in the response body, so no retry
    expect(fetchMock).toHaveBeenCalledTimes(1)
  })
})

