      body: { cancel: vi.fn() },
    }) as typeof fetch

    await expect(fetchPullRequestFiles("owner/repo", "main", "feature", "token")).rejects.toThrow(
      GitHubRateLimitError,
    )
  })

  it("paginates PR files across multiple pages", async () => {
    const page1 = Array.from({ length: 100 }, (_, i) => ({
      filename: `file${i}.ts`,
      status: "modified",
      additions: 1,
      deletions: 0,
      patch: "diff",
    }))
    const page2 = Array.from({ length: 50 }, (_, i) => ({
      filename: `file${100 + i}.ts`,
      status: "modified",
      additions: 1,
      deletions: 0,
      patch: "diff",
    }))

    const fetchMock = vi
      .fn()
      .mockResolvedValueOnce({
        ok: true,
        status: 200,
        headers: new Headers(),
        json: async () => [{ number: 1, merged_at: "2025-01-01" }],
      })
      .mockResolvedValueOnce({
        ok: true,
        status: 200,
        headers: new Headers(),
        json: async () => page1,
      })
      .mockResolvedValueOnce({
        ok: true,
        status: 200,
        headers: new Headers(),
        json: async () => page2,
      })
    globalThis.fetch = fetchMock as typeof fetch

    const result = await fetchPullRequestFiles("owner/repo", "main", "feature", "token")

    expect(result.files).toHaveLength(150)
    expect(fetchMock).toHaveBeenCalledTimes(3) // search + 2 pages
  })

  it("skips non-merged PRs to find the merged one", async () => {
    const fetchMock = vi
      .fn()
      .mockResolvedValueOnce({
        ok: true,
        status: 200,
        headers: new Headers(),
        json: async () => [
          { number: 10, merged_at: null },
          { number: 9, merged_at: "2025-01-01" },
        ],
      })
      .mockResolvedValueOnce({
        ok: true,
        status: 200,
        headers: new Headers(),
        json: async () => [
          { filename: "a.ts", status: "added", additions: 1, deletions: 0, patch: "diff" },
        ],
      })
    globalThis.fetch = fetchMock as typeof fetch

    await fetchPullRequestFiles("owner/repo", "main", "feature", "token")

    // Should use PR #9 (the merged one)
    const filesUrl = fetchMock.mock.calls[1][0] as string
    expect(filesUrl).toContain("/pulls/9/files")
  })

  it("throws GitHubRateLimitError during file pagination", async () => {
    const fetchMock = vi
      .fn()
      .mockResolvedValueOnce({
        ok: true,
        status: 200,
        headers: new Headers(),
        json: async () => [{ number: 1, merged_at: "2025-01-01" }],
      })
      .mockResolvedValueOnce({
        ok: false,
        status: 429,
        headers: new Headers({ "X-RateLimit-Reset": "1700000000" }),
        body: { cancel: vi.fn() },
      })
    globalThis.fetch = fetchMock as typeof fetch

    await expect(fetchPullRequestFiles("owner/repo", "main", "feature", "token")).rejects.toThrow(
      GitHubRateLimitError,
    )
  })
})

