        status: 422,
        text: async () => "A pull request already exists for owner:feature",
      })
      // 3rd: list open PRs
      .mockResolvedValueOnce({
        ok: true,
        json: async () => [{ number: 99 }],
      })
    globalThis.fetch = fetchMock as typeof fetch

    const result = await createPullRequest(
      "owner/repo",
