describe("fetchBranchProtection", () => {
  const originalFetch = globalThis.fetch

  beforeEach(() => {
    vi.restoreAllMocks()
  })

  afterEach(() => {
    globalThis.fetch = originalFetch
  })

  it("returns unprotected when branch is not protected", async () => {
    const fetchMock = vi.fn().mockResolvedValueOnce({
      ok: true,
      json: async () => ({ protected: false }),
    })
    globalThis.fetch = fetchMock as typeof fetch

    const result = await fetchBranchProtection("owner/repo", "main", "token")
    expect(result.protected).toBe(false)
    expect(result.has_required_pull_requests).toBe(false)
    expect(result.has_merge_queue).toBe(false)
    expect(result.has_required_status_checks).toBe(false)
    expect(fetchMock).toHaveBeenCalledTimes(1)
  })

  it("returns detailed protection when branch is protected and details accessible", async () => {
    const fetchMock = vi
      .fn()
      .mockResolvedValueOnce({
        ok: true,
        json: async () => ({ protected: true }),
      })
      .mockResolvedValueOnce({
        ok: true,
        json: async () => ({
          required_pull_request_reviews: { required_approving_review_count: 1 },
          required_status_checks: { contexts: ["ci/test"] },
          required_linear_history: { enabled: false },
        }),
      })
    globalThis.fetch = fetchMock as typeof fetch

    const result = await fetchBranchProtection("owner/repo", "main", "token")
    expect(result.protected).toBe(true)
    expect(result.has_required_pull_requests).toBe(true)
    expect(result.has_required_status_checks).toBe(true)
    expect(result.has_merge_queue).toBe(false)
  })

  it("returns indeterminate when protection details return 403", async () => {
    const fetchMock = vi
      .fn()
      .mockResolvedValueOnce({
        ok: true,
        json: async () => ({ protected: true }),
      })
      .mockResolvedValueOnce({
        ok: false,
        status: 403,
        body: { cancel: vi.fn() },
      })
    globalThis.fetch = fetchMock as typeof fetch

    const result = await fetchBranchProtection("owner/repo", "main", "token")
    expect(result.protected).toBe(true)
    expect(result.has_required_pull_requests).toBeNull()
    expect(result.has_merge_queue).toBeNull()
    expect(result.has_required_status_checks).toBeNull()
  })

  it("returns unprotected when branch endpoint fails", async () => {
    const fetchMock = vi.fn().mockResolvedValueOnce({
      ok: false,
      status: 404,
      body: { cancel: vi.fn() },
    })
    globalThis.fetch = fetchMock as typeof fetch

    const result = await fetchBranchProtection("owner/repo", "main", "token")
    expect(result.protected).toBe(false)
  })

  it("detects merge queue via required_linear_history", async () => {
    const fetchMock = vi
      .fn()
      .mockResolvedValueOnce({
        ok: true,
        json: async () => ({ protected: true }),
      })
      .mockResolvedValueOnce({
        ok: true,
        json: async () => ({
          required_linear_history: { enabled: true },
        }),
      })
    globalThis.fetch = fetchMock as typeof fetch

    const result = await fetchBranchProtection("owner/repo", "main", "token")
    expect(result.has_merge_queue).toBe(true)
    expect(result.has_required_pull_requests).toBe(false)
    expect(result.has_required_status_checks).toBe(false)
  })
})

