import { describe, it, expect, beforeAll, beforeEach, afterAll } from "vitest"

import type { CheckpointWebhookData } from "../../src/lib/db/checkpoints"
import {
  upsertCheckpointBatch,
  upsertCheckpointCommitBatch,
  getCheckpointsForBranch,
  getCommitsForBranch,
  getBranchesWithCheckpoints,
  deleteCheckpointCommitsByBranch,
  deleteOrphanedCheckpoints,
  recalculateCheckpointCount,
  getCheckpointsByUser,
} from "../../src/lib/planetscale/checkpoints"
import {
  getTestKysely,
  resetMySQLDatabase,
  destroyTestKysely,
  createTestUser,
  createTestRepo,
  linkUserToRepo,
  createTestCheckpoint,
  createTestCommit,
} from "./mysql-test-client"

function makeCheckpointWebhookData(
  overrides: Partial<CheckpointWebhookData> & { checkpoint_id: string; created_at: string },
): CheckpointWebhookData {
  return {
    prompt: null,
    agent: "Claude Code",
    steps: 1,
    session_count: 1,
    strategy: null,
    branch: null,
    session_id: null,
    files_touched: null,
    session_ids: null,
    transcript_uuid_at_start: null,
    transcript_lines_at_start: null,
    checkpoint_transcript_start: null,
    input_tokens: null,
    cache_creation_tokens: null,
    cache_read_tokens: null,
    output_tokens: null,
    api_call_count: null,
    attribution_agent_lines: null,
    attribution_human_added: null,
    attribution_human_modified: null,
    attribution_human_removed: null,
    attribution_total_committed: null,
    attribution_agent_percentage: null,
    attribution_calculated_at: null,
    sessions: null,
    ...overrides,
  }
}

describe("planetscale/checkpoints", () => {
  const db = getTestKysely()
  // --- upsertCheckpointBatch ---

  describe("upsertCheckpointBatch", () => {
    it("inserts new checkpoints", async () => {
      const repo = await createTestRepo(db)

      const count = await upsertCheckpointBatch(db, repo.id, [
        makeCheckpointWebhookData({
          checkpoint_id: "cp-1",
          prompt: "Fix bug",
          steps: 3,
          created_at: new Date().toISOString(),
          branch: "main",
          files_touched: ["src/index.ts"],
        }),
      ])

      expect(count).toBe(1)

      const rows = await db
        .selectFrom("repo_checkpoints")
        .selectAll()
        .where("repo_id", "=", repo.id)
        .execute()

      expect(rows).toHaveLength(1)
      expect(rows[0].checkpoint_id).toBe("cp-1")
      expect(rows[0].prompt).toBe("Fix bug")
    })

    it("updates existing checkpoint on duplicate", async () => {
      const repo = await createTestRepo(db)

      await upsertCheckpointBatch(db, repo.id, [
        makeCheckpointWebhookData({
          checkpoint_id: "cp-dup",
          prompt: "Original",
          created_at: new Date().toISOString(),
          branch: "main",
        }),
      ])

      await upsertCheckpointBatch(db, repo.id, [
        makeCheckpointWebhookData({
          checkpoint_id: "cp-dup",
          prompt: "Updated",
          steps: 5,
          session_count: 2,
          strategy: "test",
          created_at: new Date().toISOString(),
          branch: "main",
          files_touched: ["file.ts"],
        }),
      ])

      const rows = await db
        .selectFrom("repo_checkpoints")
        .selectAll()
        .where("repo_id", "=", repo.id)
        .execute()

      expect(rows).toHaveLength(1)
      expect(rows[0].prompt).toBe("Updated")
      expect(rows[0].steps).toBe(5)
    })

    it("returns 0 for empty input", async () => {
      const repo = await createTestRepo(db)
      const count = await upsertCheckpointBatch(db, repo.id, [])
      expect(count).toBe(0)
    })
  })

  // --- upsertCheckpointCommitBatch ---

  describe("upsertCheckpointCommitBatch", () => {
    it("inserts new commits", async () => {
      const repo = await createTestRepo(db)
      await createTestCheckpoint(db, repo.id, { checkpoint_id: "cp-commit-1" })

      const count = await upsertCheckpointCommitBatch(db, repo.id, "main", [
        {
          checkpoint_id: "cp-commit-1",
          commit_sha: "abc123",
        },
      ])

      expect(count).toBe(1)

      const rows = await db
        .selectFrom("repo_checkpoint_commits")
        .selectAll()
        .where("repo_id", "=", repo.id)
        .execute()

      expect(rows).toHaveLength(1)
      expect(rows[0].commit_sha).toBe("abc123")
      expect(rows[0].branch).toBe("main")
    })

    it("updates existing commit on duplicate", async () => {
      const repo = await createTestRepo(db)
      await createTestCheckpoint(db, repo.id, { checkpoint_id: "cp-commit-dup" })

      await upsertCheckpointCommitBatch(db, repo.id, "main", [
        {
          checkpoint_id: "cp-commit-dup",
          commit_sha: "old-sha",
        },
      ])

      await upsertCheckpointCommitBatch(db, repo.id, "main", [
        {
          checkpoint_id: "cp-commit-dup",
          commit_sha: "new-sha",
        },
      ])

      const rows = await db
        .selectFrom("repo_checkpoint_commits")
        .selectAll()
        .where("repo_id", "=", repo.id)
        .execute()

      expect(rows).toHaveLength(1)
      expect(rows[0].commit_sha).toBe("new-sha")
    })
  })

  // --- getCheckpointsForBranch ---

  describe("getCheckpointsForBranch", () => {
    it("returns checkpoints with commit data for a branch", async () => {
      const repo = await createTestRepo(db)
      const cpId = "cp-branch-1"
      await createTestCheckpoint(db, repo.id, { checkpoint_id: cpId, prompt: "Do thing" })
      await createTestCommit(db, repo.id, cpId, "main", {
        commit_sha: "sha1",
        commit_message: "implemented thing",
        additions: 15,
      })

      const checkpoints = await getCheckpointsForBranch(db, repo.id, "main")

      expect(checkpoints).toHaveLength(1)
      expect(checkpoints[0].checkpoint_id).toBe(cpId)
      expect(checkpoints[0].commit_sha).toBe("sha1")
      expect(checkpoints[0].prompt).toBe("Do thing")
      expect(checkpoints[0].additions).toBe(15)
    })

    it("returns empty array when no commits on branch", async () => {
      const repo = await createTestRepo(db)
      const checkpoints = await getCheckpointsForBranch(db, repo.id, "main")
      expect(checkpoints).toEqual([])
    })

    it("respects limit parameter", async () => {
      const repo = await createTestRepo(db)

      for (let i = 0; i < 5; i++) {
        const cpId = `cp-limit-${i}`
        await createTestCheckpoint(db, repo.id, { checkpoint_id: cpId })
        await createTestCommit(db, repo.id, cpId, "main", {
          commit_date: new Date(Date.now() - i * 1000),
        })
      }

      const checkpoints = await getCheckpointsForBranch(db, repo.id, "main", { limit: 3 })
      expect(checkpoints).toHaveLength(3)
    })

    it("only returns commits for specified branch", async () => {
      const repo = await createTestRepo(db)
      const cpId = "cp-multi-branch"
      await createTestCheckpoint(db, repo.id, { checkpoint_id: cpId })
      await createTestCommit(db, repo.id, cpId, "main")
      await createTestCommit(db, repo.id, cpId, "feature")

      const mainCheckpoints = await getCheckpointsForBranch(db, repo.id, "main")
      expect(mainCheckpoints).toHaveLength(1)

      const featureCheckpoints = await getCheckpointsForBranch(db, repo.id, "feature")
      expect(featureCheckpoints).toHaveLength(1)
    })
  })

  describe("getCommitsForBranch", () => {
    it("deduplicates duplicate checkpoint rows for the same commit", async () => {
      const repo = await createTestRepo(db)
      const checkpointId = "cp-dup-commit-list"
      const commitSha = "sha-dup-1"

      await createTestCheckpoint(db, repo.id, {
        checkpoint_id: checkpointId,
        prompt: "Do thing",
        created_at: new Date(),
      })

      await createTestCommit(db, repo.id, checkpointId, "main", {
        commit_sha: commitSha,
        commit_message: "Add thing",
      })

      await db
        .insertInto("repo_branch_commits")
        .values({
          id: crypto.randomUUID(),
          repo_id: repo.id,
          branch: "feature",
          commit_sha: commitSha,
        })
        .execute()

      await db
        .insertInto("repo_checkpoint_commits")
        .values({
          id: crypto.randomUUID(),
          repo_id: repo.id,
          checkpoint_id: checkpointId,
          branch: "feature",
          commit_sha: commitSha,
        })
        .execute()

      const commits = await getCommitsForBranch(db, repo.id, "main")

      expect(commits).toHaveLength(1)
      expect(commits[0]?.checkpoints).toHaveLength(1)
      expect(commits[0]?.checkpoints[0]?.checkpoint_id).toBe(checkpointId)
    })

    it("keeps distinct checkpoints attached to the same commit", async () => {
      const repo = await createTestRepo(db)
      const commitSha = "sha-shared-1"

      await createTestCheckpoint(db, repo.id, {
        checkpoint_id: "cp-distinct-1",
        prompt: "First prompt",
        created_at: new Date(),
      })
      await createTestCheckpoint(db, repo.id, {
        checkpoint_id: "cp-distinct-2",
        prompt: "Second prompt",
        created_at: new Date(),
      })

      await createTestCommit(db, repo.id, "cp-distinct-1", "main", {
        commit_sha: commitSha,
        commit_message: "Shared commit",
      })

      await db
        .insertInto("repo_checkpoint_commits")
        .values({
          id: crypto.randomUUID(),
          repo_id: repo.id,
          checkpoint_id: "cp-distinct-2",
          branch: "main",
          commit_sha: commitSha,
        })
        .execute()

      const commits = await getCommitsForBranch(db, repo.id, "main")

      expect(commits).toHaveLength(1)
      expect(commits[0]?.checkpoints).toHaveLength(2)
      expect(commits[0]?.checkpoints.map((checkpoint) => checkpoint.checkpoint_id).sort()).toEqual([
        "cp-distinct-1",
        "cp-distinct-2",
      ])
    })
  })

  // --- getBranchesWithCheckpoints ---

  describe("getBranchesWithCheckpoints", () => {
    it("returns branches with commit counts", async () => {
      const repo = await createTestRepo(db)

      // 2 commits on main, 1 on feature
      const cp1 = "cp-br-1"
      const cp2 = "cp-br-2"
      const cp3 = "cp-br-3"
      await createTestCheckpoint(db, repo.id, { checkpoint_id: cp1 })
      await createTestCheckpoint(db, repo.id, { checkpoint_id: cp2 })
      await createTestCheckpoint(db, repo.id, { checkpoint_id: cp3 })
      await createTestCommit(db, repo.id, cp1, "main")
      await createTestCommit(db, repo.id, cp2, "main")
      await createTestCommit(db, repo.id, cp3, "feature")

      const branches = await getBranchesWithCheckpoints(db, repo.id)

      expect(branches).toHaveLength(2)
      // Sorted by count desc
      expect(branches[0].branch).toBe("main")
      expect(branches[0].checkpoint_count).toBe(2)
      expect(branches[1].branch).toBe("feature")
      expect(branches[1].checkpoint_count).toBe(1)
    })

    it("returns empty array when no commits", async () => {
      const repo = await createTestRepo(db)
      const branches = await getBranchesWithCheckpoints(db, repo.id)
      expect(branches).toEqual([])
    })
  })

  // --- deleteCheckpointCommitsByBranch ---

  describe("deleteCheckpointCommitsByBranch", () => {
    it("deletes checkpoint_commit rows for a specific branch", async () => {
      const repo = await createTestRepo(db)
      const cp1 = "cp-on-main"
      const cp2 = "cp-on-feature"
      await createTestCheckpoint(db, repo.id, { checkpoint_id: cp1 })
      await createTestCheckpoint(db, repo.id, { checkpoint_id: cp2 })
      await createTestCommit(db, repo.id, cp1, "main")
      await createTestCommit(db, repo.id, cp2, "feature")

      const count = await deleteCheckpointCommitsByBranch(db, repo.id, "main")
      expect(count).toBe(1)

      const remaining = await db
        .selectFrom("repo_checkpoint_commits")
        .selectAll()
        .where("repo_id", "=", repo.id)
        .execute()
      expect(remaining).toHaveLength(1)
      expect(remaining[0].checkpoint_id).toBe(cp2)
    })
  })

  // --- deleteOrphanedCheckpoints ---

  describe("deleteOrphanedCheckpoints", () => {
    it("deletes checkpoints without commits (past grace period)", async () => {
      const repo = await createTestRepo(db)

      // Create an orphaned checkpoint (old enough to be past grace period)
      const fiveMinutesAgo = new Date(Date.now() - 6 * 60 * 1000)
      await createTestCheckpoint(db, repo.id, {
        checkpoint_id: "cp-orphan",
        created_at: fiveMinutesAgo,
      })

      // Create a checkpoint with a commit (should not be deleted)
      const cpWithCommit = "cp-has-commit"
      await createTestCheckpoint(db, repo.id, { checkpoint_id: cpWithCommit })
      await createTestCommit(db, repo.id, cpWithCommit, "main")

      const count = await deleteOrphanedCheckpoints(db, repo.id)
      expect(count).toBe(1)

      const remaining = await db
        .selectFrom("repo_checkpoints")
        .selectAll()
        .where("repo_id", "=", repo.id)
        .execute()

      expect(remaining).toHaveLength(1)
      expect(remaining[0].checkpoint_id).toBe(cpWithCommit)
    })

    it("does not delete recent orphaned checkpoints (grace period)", async () => {
      const repo = await createTestRepo(db)

      // Create a recent orphaned checkpoint (within grace period)
      await createTestCheckpoint(db, repo.id, {
        checkpoint_id: "cp-recent-orphan",
        created_at: new Date(), // just now
      })

      const count = await deleteOrphanedCheckpoints(db, repo.id)
      expect(count).toBe(0)
    })
  })

  // --- recalculateCheckpointCount ---

  describe("recalculateCheckpointCount", () => {
    it("updates checkpoint_count on the repo", async () => {
      const repo = await createTestRepo(db, { checkpoint_count: 0 })

      const cp1 = "cp-count-1"
      const cp2 = "cp-count-2"
      await createTestCheckpoint(db, repo.id, { checkpoint_id: cp1 })
      await createTestCheckpoint(db, repo.id, { checkpoint_id: cp2 })
      await createTestCommit(db, repo.id, cp1, "main")
      await createTestCommit(db, repo.id, cp2, "main")

      await recalculateCheckpointCount(db, repo.id)

      const updated = await db
        .selectFrom("repos")
        .select("checkpoint_count")
        .where("id", "=", repo.id)
        .executeTakeFirstOrThrow()

      expect(updated.checkpoint_count).toBe(2)
    })

    it("sets count to 0 when no commits exist", async () => {
      const repo = await createTestRepo(db, { checkpoint_count: 5 })

      await recalculateCheckpointCount(db, repo.id)

      const updated = await db
        .selectFrom("repos")
        .select("checkpoint_count")
        .where("id", "=", repo.id)
        .executeTakeFirstOrThrow()

      expect(updated.checkpoint_count).toBe(0)
    })

    it("counts distinct checkpoint_ids (not duplicate branches)", async () => {
      const repo = await createTestRepo(db)
      const cpId = "cp-dedup"
      await createTestCheckpoint(db, repo.id, { checkpoint_id: cpId })
      await createTestCommit(db, repo.id, cpId, "main")
      await createTestCommit(db, repo.id, cpId, "feature") // same checkpoint, different branch

      await recalculateCheckpointCount(db, repo.id)

      const updated = await db
        .selectFrom("repos")
        .select("checkpoint_count")
        .where("id", "=", repo.id)
        .executeTakeFirstOrThrow()

      expect(updated.checkpoint_count).toBe(1) // distinct checkpoint_id
    })
  })

  // --- getCheckpointsByUser ---

  describe("getCheckpointsByUser", () => {
    async function setupUserWithCheckpoint(
      options: {
        checkpointId?: string
        sourceBranch?: string | null
        commitBranches?: string[]
        githubId?: number
        commitDate?: Date
      } = {},
    ) {
      const githubId = options.githubId ?? 12345
      const checkpointId = options.checkpointId ?? `cp-${Date.now()}`
      const sourceBranch = options.sourceBranch ?? "feature-branch"
      const commitBranches = options.commitBranches ?? ["feature-branch"]
      const commitDate = options.commitDate ?? new Date()

      const user = await createTestUser(db, { github_id: githubId })
      const repo = await createTestRepo(db)
      await linkUserToRepo(db, user.id, repo.id)

      await createTestCheckpoint(db, repo.id, {
        checkpoint_id: checkpointId,
        branch: sourceBranch,
      })

      for (const branch of commitBranches) {
        await createTestCommit(db, repo.id, checkpointId, branch, {
          commit_author_github_id: githubId,
          commit_date: commitDate,
        })
      }

      return { user, repo, checkpointId, githubId }
    }

    it("returns checkpoints for a user", async () => {
      const { user, githubId, checkpointId } = await setupUserWithCheckpoint()

      const startDate = new Date(Date.now() - 86400000).toISOString()
      const endDate = new Date(Date.now() + 86400000).toISOString()

      const results = await getCheckpointsByUser(db, user.id, githubId, startDate, endDate)

      expect(results).toHaveLength(1)
      expect(results[0].checkpoint_id).toBe(checkpointId)
      expect(results[0].commit_sha).toBeTruthy()
      expect(results[0].branch).toBe("feature-branch")
    })

    it("respects limit", async () => {
      const githubId = 12345

      const user = await createTestUser(db, { github_id: githubId })
      const repo = await createTestRepo(db)
      await linkUserToRepo(db, user.id, repo.id)

      // Create 5 checkpoints, each with 1 commit row
      for (let i = 0; i < 5; i++) {
        const checkpointId = `cp-limit-test-${i}`
        const commitDate = new Date(Date.now() - i * 1000)

        await createTestCheckpoint(db, repo.id, {
          checkpoint_id: checkpointId,
          branch: "main",
        })

        await createTestCommit(db, repo.id, checkpointId, "main", {
          commit_author_github_id: githubId,
          commit_date: commitDate,
        })
      }

      const startDate = new Date(Date.now() - 86400000).toISOString()
      const endDate = new Date(Date.now() + 86400000).toISOString()

      const results = await getCheckpointsByUser(db, user.id, githubId, startDate, endDate, 3)

      expect(results).toHaveLength(3)
      const uniqueCheckpointIds = new Set(results.map((r) => r.checkpoint_id))
      expect(uniqueCheckpointIds.size).toBe(3)
    })

    it("returns empty array for user with no repos", async () => {
      const user = await createTestUser(db, { github_id: 99999 })

      const startDate = new Date(Date.now() - 86400000).toISOString()
      const endDate = new Date(Date.now() + 86400000).toISOString()

      const results = await getCheckpointsByUser(db, user.id, 99999, startDate, endDate)

      expect(results).toEqual([])
    })

    it("returns empty array for user with repos but no checkpoints", async () => {
      const githubId = 88888
      const user = await createTestUser(db, { github_id: githubId })
      const repo = await createTestRepo(db)
      await linkUserToRepo(db, user.id, repo.id)

      const startDate = new Date(Date.now() - 86400000).toISOString()
      const endDate = new Date(Date.now() + 86400000).toISOString()

      const results = await getCheckpointsByUser(db, user.id, githubId, startDate, endDate)

      expect(results).toEqual([])
    })
  })
})

