import { describe, it, expect } from "vitest"

import {
  deduplicateCheckpoints,
  deduplicateCommits,
  type CheckpointData,
  type CommitData,
} from "./repo-sync-service"

// Minimal checkpoint for testing deduplication
function makeCheckpoint(
  checkpoint_id: string,
  overrides: Partial<CheckpointData> = {},
): CheckpointData {
  return {
    checkpoint_id,
    prompt: null,
    agent: "Claude Code",
    steps: 1,
    session_count: 1,
    strategy: null,
    branch: "main",
    session_id: null,
    files_touched: null,
    session_ids: null,
    transcript_uuid_at_start: null,
    transcript_lines_at_start: null,
    checkpoint_transcript_start: null,
    input_tokens: null,
    cache_creation_tokens: null,
    cache_read_tokens: null,
    output_tokens: null,
    api_call_count: null,
    sessions: null,
    created_at: new Date().toISOString(),
    ...overrides,
  }
}

// Minimal commit for testing deduplication
function makeCommit(
  checkpoint_id: string,
  branch: string,
  overrides: Partial<CommitData> = {},
): CommitData {
  return {
    checkpoint_id,
    branch,
    commit_sha: "abc123",
    ...overrides,
  }
}

describe("repo-sync-service deduplication", () => {
  describe("deduplicateCheckpoints", () => {
    it("returns empty array for empty input", () => {
      expect(deduplicateCheckpoints([])).toEqual([])
    })

    it("returns all checkpoints when no duplicates", () => {
      const checkpoints = [makeCheckpoint("cp-1"), makeCheckpoint("cp-2"), makeCheckpoint("cp-3")]
      const result = deduplicateCheckpoints(checkpoints)
      expect(result).toHaveLength(3)
      expect(result.map((c) => c.checkpoint_id)).toEqual(["cp-1", "cp-2", "cp-3"])
    })

    it("removes duplicate checkpoint_ids, keeping first occurrence", () => {
      const checkpoints = [
        makeCheckpoint("cp-1", { prompt: "first" }),
        makeCheckpoint("cp-2"),
        makeCheckpoint("cp-1", { prompt: "duplicate" }), // duplicate
        makeCheckpoint("cp-3"),
        makeCheckpoint("cp-2", { prompt: "another duplicate" }), // duplicate
      ]
      const result = deduplicateCheckpoints(checkpoints)
      expect(result).toHaveLength(3)
      expect(result.map((c) => c.checkpoint_id)).toEqual(["cp-1", "cp-2", "cp-3"])
      // First occurrence is kept
      expect(result[0].prompt).toBe("first")
      expect(result[1].prompt).toBeNull()
    })

    it("handles all duplicates of same checkpoint", () => {
      const checkpoints = [
        makeCheckpoint("cp-1", { branch: "main" }),
        makeCheckpoint("cp-1", { branch: "feature" }),
        makeCheckpoint("cp-1", { branch: "develop" }),
      ]
      const result = deduplicateCheckpoints(checkpoints)
      expect(result).toHaveLength(1)
      expect(result[0].branch).toBe("main") // first occurrence
    })
  })

  describe("deduplicateCommits", () => {
    it("returns empty array for empty input", () => {
      expect(deduplicateCommits([])).toEqual([])
    })

    it("returns all commits when no duplicates", () => {
      const commits = [
        makeCommit("cp-1", "main"),
        makeCommit("cp-1", "feature"), // same checkpoint, different branch = unique
        makeCommit("cp-2", "main"),
      ]
      const result = deduplicateCommits(commits)
      expect(result).toHaveLength(3)
    })

    it("removes duplicates with same checkpoint_id AND branch", () => {
      const commits = [
        makeCommit("cp-1", "main", { commit_sha: "first" }),
        makeCommit("cp-1", "feature"),
        makeCommit("cp-1", "main", { commit_sha: "duplicate" }), // duplicate: same cp + branch
        makeCommit("cp-2", "main"),
      ]
      const result = deduplicateCommits(commits)
      expect(result).toHaveLength(3)
      // First occurrence is kept
      const mainCommit = result.find((c) => c.checkpoint_id === "cp-1" && c.branch === "main")
      expect(mainCommit?.commit_sha).toBe("first")
    })

    it("keeps commits with same checkpoint but different branches", () => {
      const commits = [
        makeCommit("cp-1", "main"),
        makeCommit("cp-1", "feature"),
        makeCommit("cp-1", "develop"),
      ]
      const result = deduplicateCommits(commits)
      expect(result).toHaveLength(3)
      expect(result.map((c) => c.branch)).toEqual(["main", "feature", "develop"])
    })
  })
})

