  | "unknown"

export interface AgentConfig {
  id: AgentId
  label: string
  logoUrl: string
  colorClass: string
  /** When true, the logo fills the full avatar circle (no white border/inset). */
  fullBleed?: boolean
}

export const agents: Record<AgentId, AgentConfig> = {
  claude: {
    id: "claude",
    label: "Claude Code",
    logoUrl: "/images/logos/agents/claude.svg",
    colorClass: "agent-claude",
  },
