    logoUrl: "/images/logos/agents/amp.svg",
    colorClass: "agent-amp",
  },
  codex: {
    id: "codex",
    label: "Codex",
    logoUrl: "/images/logos/agents/codex.svg",
    colorClass: "agent-codex",
  },
  opencode: {
    id: "opencode",
    label: "OpenCode",
    logoUrl: "/images/logos/agents/opencode.svg",
    colorClass: "agent-opencode",
  },
  copilot: {
    id: "copilot",
    label: "Copilot",
    logoUrl: "/images/logos/agents/copilot.svg",
    colorClass: "agent-copilot",
  },
  pi: {
    id: "pi",
    label: "Pi",
    logoUrl: "/images/logos/agents/pi.svg",
    colorClass: "agent-pi",
  },
  cursor: {
    id: "cursor",
    label: "Cursor",
    logoUrl: "/images/logos/agents/cursor.svg",
    colorClass: "agent-cursor",
  },
  droid: {
    id: "droid",
    label: "Factory AI Droid",
    logoUrl: "/images/logos/agents/droid.svg",
    colorClass: "agent-droid",
  },
  kiro: {
    id: "kiro",
    label: "Kiro",
    logoUrl: "/images/logos/agents/kiro.svg",
    colorClass: "agent-kiro",
    fullBleed: true,
  },
  unknown: {
    id: "unknown",
    label: "Agent",
    logoUrl: "",
    colorClass: "agent-default",
  },
}

// Eval agents — use the same Claude logo since they run Claude
const evalAgents: Record<string, AgentConfig> = {
  "risk-eval": {
    id: "claude" as AgentId,
    label: "Risk Eval",
    logoUrl: "/images/logos/agents/claude.svg",
    colorClass: "agent-claude",
  },
}

// Normalize an agent string to try matching against known IDs.
// Handles variations like "Claude Code", "claude-code", "open code",
// "open-code", "OpenCode", "copilot cli", "Gemini CLI", etc.
function normalizeAgentId(id: string): AgentId | null {
  const lower = id.trim().toLowerCase()

  // Direct lowercase match (e.g. "claude", "opencode", "copilot")
  if (lower in agents) return lower as AgentId

  // Collapse separators first (e.g. "open code" / "open-code" -> "opencode")
  const collapsed = lower.replace(/[- ]/g, "")
  if (collapsed in agents) return collapsed as AgentId

  // Strip common suffixes: " code", "-code", " cli", "-cli"
  const stripped = lower.replace(/[- ](code|cli)$/, "")
  if (stripped in agents) return stripped as AgentId

  // Strip suffixes then collapse (e.g. "Open Code CLI" -> "open code" -> "opencode")
  const strippedCollapsed = stripped.replace(/[- ]/g, "")
  if (strippedCollapsed in agents) return strippedCollapsed as AgentId

  // Handle "Factory AI Droid" and variations
  if (collapsed.includes("factoryaidroid")) return "droid"

  return null
}

export function getAgent(id: string | null | undefined): AgentConfig {
  if (!id) return agents.unknown
  if (id in agents) return agents[id as AgentId]
  if (id in evalAgents) return evalAgents[id]
  const normalized = normalizeAgentId(id)
  return normalized ? agents[normalized] : agents.unknown
}

// Check if an agent string matches a known agent ID
export function isKnownAgent(id: string | null | undefined): id is string {
  if (!id) return false
  if (id in agents) return true
  return normalizeAgentId(id) !== null
}

export function getAgentId(id: string | null | undefined): AgentId {
  if (!id) return "unknown"
  if (id in agents) return id as AgentId
  return normalizeAgentId(id) ?? "unknown"
}

